messages.content:
{
 "candidates": [
  {
   "ref": "C001",
   "source_doc_id": "D01",
   "name": "Material Volume Report",
   "description": "The system must provide a material volume report for a specified library that counts all items assigned to that library and reports the total volume together with separate counts for new acquisitions, items on the shelf (checked in), and items out in circulation (checked out). Checked-out items must be included in the total volume."
  },
  {
   "ref": "C002",
   "source_doc_id": "D01",
   "name": "Category Volume Breakdown",
   "description": "The report must break material volume down by categories, including total items, number of holds, adult fiction, and board books, with holds counts shown for each category where applicable."
  },
  {
   "ref": "C003",
   "source_doc_id": "D01",
   "name": "Custom Report Categories",
   "description": "The system must allow libraries to define customizable categories for the material volume breakdown so that different libraries can use different category groupings, such as fiction/non-fiction or format."
  },
  {
   "ref": "C004",
   "source_doc_id": "D01",
   "name": "Historical Volume Reporting",
   "description": "The system must allow users to report a library's material volume at any point in time, using date filters to support historical comparisons rather than limiting the report to the current volume."
  },
  {
   "ref": "C005",
   "source_doc_id": "D01",
   "name": "Acquisition Volume Trends",
   "description": "The system must use item acquisition dates to show how much material volume was added during selectable periods, including the last 30, 60, or 90 days."
  },
  {
   "ref": "C006",
   "source_doc_id": "D02",
   "name": "All-Branch Capacity Overview",
   "description": "The system must provide branch managers and other authorized users with a high-level view showing the capacity of all branches at once, so they can compare locations when moving items or allocating resources."
  },
  {
   "ref": "C007",
   "source_doc_id": "D02",
   "name": "Branch Capacity Drilldown",
   "description": "The system must allow users viewing the all-branch capacity overview to drill down into the capacity information for an individual branch."
  },
  {
   "ref": "C008",
   "source_doc_id": "D02",
   "name": "Branch Capacity Sorting",
   "description": "The system must allow users to sort the branches shown in the capacity interface, including by region, library type, and current load."
  },
  {
   "ref": "C009",
   "source_doc_id": "D02",
   "name": "Branch Capacity Filtering",
   "description": "The system must allow users to filter the branches shown in the capacity interface by region, library type, and current load, including when the system contains 286 locations."
  },
  {
   "ref": "C010",
   "source_doc_id": "D02",
   "name": "Capacity Trend Display",
   "description": "The system must show branch capacity trends, including whether each branch is growing or shrinking, to support long-term planning."
  },
  {
   "ref": "C011",
   "source_doc_id": "D02",
   "name": "Capacity CSV Export",
   "description": "The system must allow users to export the capacity interface data to CSV so directors can use it in spreadsheets."
  },
  {
   "ref": "C012",
   "source_doc_id": "D03",
   "name": "Shelf Space Usage Report",
   "description": "The system must provide a report for each genre and format of material that compares the percentage of total circulations, the percentage of the collection, and the percentage of total shelf space. It must support views per library and for the entire system, allow users to specify a date range such as Q1 or Q2, count items for collection percentages, sum checkouts for circulation percentages, and estimate shelf space using available item dimensions or item count as a proxy when direct shelf-space data is unavailable."
  },
  {
   "ref": "C013",
   "source_doc_id": "D03",
   "name": "Library Breakdown Comparison",
   "description": "The system must provide a comparison view showing each library’s shelf-space report breakdown side by side, including the genre-and-format percentages for circulations, collection holdings, and shelf space, so users can identify differences and outliers among libraries."
  },
  {
   "ref": "C014",
   "source_doc_id": "D04",
   "name": "Batch Item Transfers",
   "description": "The system must allow authorized staff to transfer batches of items between branches or other locations, including mobile libraries, outreach programs, warehouses, book sales, and event locations, by moving selected items to a new location."
  },
  {
   "ref": "C015",
   "source_doc_id": "D04",
   "name": "Candidate Material Queries",
   "description": "The system must provide a query builder that allows staff to identify candidate materials for an item transfer, including criteria such as genre and circulation inactivity."
  },
  {
   "ref": "C016",
   "source_doc_id": "D04",
   "name": "Saved Transfer Queries",
   "description": "The system must allow staff to save transfer queries for repeated use and make saved queries available for reuse or sharing, supporting recurring transfers such as moving items that have not circulated for six months."
  },
  {
   "ref": "C017",
   "source_doc_id": "D04",
   "name": "Manual Result Selection",
   "description": "The system must allow staff to manually select individual titles or items from query results before including them in a transfer, such as selecting 25 items from 100 candidates."
  },
  {
   "ref": "C018",
   "source_doc_id": "D04",
   "name": "Location Record Updates",
   "description": "The system must update the location field and associated item records for the selected items when they are transferred to a new location."
  },
  {
   "ref": "C019",
   "source_doc_id": "D04",
   "name": "Transfer Pull Lists",
   "description": "The system must generate printable pull lists identifying the items selected for transfer so staff can retrieve them for movement."
  },
  {
   "ref": "C020",
   "source_doc_id": "D04",
   "name": "Transfer Reversion Rules",
   "description": "The system must return transferred items to their original locations automatically after a configured period or when configured criteria occur, including a specified number of days, an item status changing to \"sold\" or \"returned,\" or an item being checked out at the destination."
  },
  {
   "ref": "C021",
   "source_doc_id": "D04",
   "name": "Transfer Audit History",
   "description": "The system must record transfer history for each item for audit and operational review, including enough history to determine transfer patterns such as whether an item has been transferred five times within the past year."
  },
  {
   "ref": "C022",
   "source_doc_id": "D04",
   "name": "Transfer Preview Confirmation",
   "description": "The system must show staff a preview of a proposed transfer before making changes, including the number of items and their source and destination locations, and require confirmation before execution."
  },
  {
   "ref": "C023",
   "source_doc_id": "D04",
   "name": "Transfer Undo",
   "description": "The system must provide an undo function that allows staff to reverse an erroneous transfer after the transfer has been initiated or completed."
  },
  {
   "ref": "C024",
   "source_doc_id": "D04",
   "name": "Transfer Role Permissions",
   "description": "The system must restrict item transfers between branches to authorized roles, including managers, administrators, and transfer coordinators, rather than allowing every staff member to perform transfers."
  },
  {
   "ref": "C025",
   "source_doc_id": "D04",
   "name": "Transit Label Generation",
   "description": "The system must generate printable transit labels containing barcodes for items being transferred."
  },
  {
   "ref": "C026",
   "source_doc_id": "D04",
   "name": "Transfer Delay Alerts",
   "description": "The system must notify designated staff when an item transfer is delayed or encounters an issue."
  },
  {
   "ref": "C027",
   "source_doc_id": "D04",
   "name": "Efficient Large Transfers",
   "description": "The system must process batch updates efficiently for an item collection of approximately 9.6 million items while avoiding excessive database locking during large transfers."
  },
  {
   "ref": "C028",
   "source_doc_id": "D05",
   "name": "Missing Damaged Items Report",
   "description": "The system must provide a report of missing and damaged items grouped per branch, including item condition notes such as “water damage” or “vandalism” and supporting selectable date ranges such as the last 30 days or last quarter. The report must support inventory auditing, collection-management decisions, and investigation of branch-level loss patterns."
  },
  {
   "ref": "C029",
   "source_doc_id": "D05",
   "name": "In-Transit Items Report",
   "description": "The system must generate one report of items that have remained in transit beyond a configurable threshold X days, with a default of 7 days, using items whose arrival date is null and whose departure date is more than X days ago. The report must cover both transit-to and transit-from items in the same result, support views per branch and per system, and allow sorting by due date so front-line staff can pursue the oldest items first."
  },
  {
   "ref": "C030",
   "source_doc_id": "D06",
   "name": "Identify Purge Candidates",
   "description": "The system must provide reports and a utility that identify item records eligible for purging using customizable criteria, including item status such as \"missing,\" \"discard/weed,\" or \"damaged\"; time spent in a status such as more than X months or years; and circulation activity such as not circulating for a specified number of days, months, or years."
  },
  {
   "ref": "C031",
   "source_doc_id": "D06",
   "name": "Combine Purge Criteria",
   "description": "The system must allow users to combine purge criteria, including status-based, time-based, and activity-based conditions, using combinations such as items with status \"missing\" for more than six months AND no circulation for two years, or damaged items that have not circulated for two or more years."
  },
  {
   "ref": "C032",
   "source_doc_id": "D06",
   "name": "Batch Convert Item Statuses",
   "description": "The system must provide a report or workflow that assists users in converting many items from one status to another in a single batch operation, such as changing 100 items from \"missing\" to \"discard/weed.\""
  },
  {
   "ref": "C033",
   "source_doc_id": "D06",
   "name": "Report Last Copies",
   "description": "The system must provide a last-copy report that flags each item record that is the only copy within a selected scope, with views per library and across the entire library system or consortium, so catalogers can update WorldCat entries and avoid deleting the only copy at either scope."
  },
  {
   "ref": "C034",
   "source_doc_id": "D06",
   "name": "Delete Volumes With Copies",
   "description": "The system must provide a quick and effective method to delete volume entries together with their associated copy entries."
  },
  {
   "ref": "C035",
   "source_doc_id": "D06",
   "name": "Delete Itemless Records",
   "description": "The system must provide a quick and effective method to delete records that have no items attached."
  },
  {
   "ref": "C036",
   "source_doc_id": "D06",
   "name": "Protect Candidate Reports",
   "description": "Reports used to identify records for purging must be read-only and must not delete or modify the reported candidate records."
  },
  {
   "ref": "C037",
   "source_doc_id": "D06",
   "name": "Confirm Purge Deletions",
   "description": "The system must require a separate confirmation step before carrying out actual purge deletions, including deletions initiated after candidate records have been identified."
  },
  {
   "ref": "C038",
   "source_doc_id": "D06",
   "name": "Audit Purge Activity",
   "description": "The system must maintain an audit trail for all purges, recording who purged each record and when, to support accountability and troubleshooting."
  },
  {
   "ref": "C039",
   "source_doc_id": "D07",
   "name": "Log Deleted Records",
   "description": "The system must record each completed deletion of a record, including the record type (such as item, patron, bib, or other), record ID, deletion timestamp, user who performed the deletion, and the location of that user, so deletions can be audited and traced across locations and systems."
  },
  {
   "ref": "C040",
   "source_doc_id": "D07",
   "name": "Report Deletion Activity",
   "description": "The system must provide an interface for querying and reporting the deletion audit records, including deletion counts per location and per system; aggregation by date range, user, and record type; totals for periods such as month, quarter, or year; deletions by location and type; and identification of users with the highest numbers of deletions."
  },
  {
   "ref": "C041",
   "source_doc_id": "D07",
   "name": "Track Denied Deletions",
   "description": "The system must record attempted deletions that are denied, so administrators can investigate unauthorized deletion attempts and support compliance and troubleshooting."
  },
  {
   "ref": "C042",
   "source_doc_id": "D08",
   "name": "Filter Patron Reports",
   "description": "The system must allow users to limit patron queries and reports by patron characteristics: age range, zip code, county of residence, home branch, patron type, and preferred language. Age range must be derived from each patron’s birth date, and the capability must support examples such as selecting patrons aged 13–18 in a specified zip code or juvenile patrons in a specified zip code who have not checked anything out in six months."
  },
  {
   "ref": "C043",
   "source_doc_id": "D08",
   "name": "Group Patron Reports",
   "description": "The system must allow users to group patron queries and reports by age range, zip code, county of residence, home branch, patron type, and preferred language, and show aggregates such as circulation or checkout counts by the selected characteristic."
  },
  {
   "ref": "C044",
   "source_doc_id": "D08",
   "name": "Combine Report Filters",
   "description": "The system must allow multiple report filters to be combined using AND and OR logic, including combinations of patron characteristics and applicable circulation conditions."
  },
  {
   "ref": "C045",
   "source_doc_id": "D08",
   "name": "Configure Age Ranges",
   "description": "The system must allow age ranges used for patron filtering and grouping to be configured for each report, including ranges such as 0–5, 6–10, 11–15 or alternative ranges such as 0–6, 7–12, 13–17, 18–24, and 25–34."
  },
  {
   "ref": "C046",
   "source_doc_id": "D08",
   "name": "Include Missing Values",
   "description": "The system must include patrons whose optional demographic fields are not populated in query and report results, representing missing values as null rather than silently excluding those patrons."
  },
  {
   "ref": "C047",
   "source_doc_id": "D09",
   "name": "Generate Inactive Patron Report",
   "description": "The system must generate a list of patrons whose circulation and electronic activity have both been absent for a configurable number of days. Electronic activity must include OPAC or patron-account logins, online hold placements, online renewals, and logged access to digital collections or resources when integrated."
  },
  {
   "ref": "C048",
   "source_doc_id": "D09",
   "name": "Configure Inactivity Period",
   "description": "The inactive patron report must allow the inactivity threshold to be set to any number of days, including commonly used values such as 30, 90, 180, and 365 days."
  },
  {
   "ref": "C049",
   "source_doc_id": "D09",
   "name": "Configure Report Scope",
   "description": "The inactive patron report must support grouping or listing results at configurable organisational levels, including System, Home Library, and County, with additional levels supported as needed. Users must be able to identify branch inactivity totals at the system level and assign cleanup work to specific branches at the home-library level."
  },
  {
   "ref": "C050",
   "source_doc_id": "D09",
   "name": "Include Mailing Addresses",
   "description": "The inactive patron report must include each inactive patron's current mailing address so that libraries can conduct postcard outreach and re-engagement campaigns."
  },
  {
   "ref": "C051",
   "source_doc_id": "D09",
   "name": "Separate Fine-Bearing Patrons",
   "description": "The system must track and present inactive patrons with outstanding fines separately from other inactive patrons so that those accounts can receive different handling."
  },
  {
   "ref": "C052",
   "source_doc_id": "D09",
   "name": "Exclude Selected Patrons",
   "description": "The inactive patron report must allow users to exclude specified patron categories or records, including patrons marked do not disturb, VIP patrons, staff members, and patrons who have opted out of communications."
  },
  {
   "ref": "C053",
   "source_doc_id": "D09",
   "name": "Export Report as CSV",
   "description": "The system must export the inactive patron report in CSV format so that the results can be uploaded to an outreach system."
  },
  {
   "ref": "C054",
   "source_doc_id": "D09",
   "name": "Process Report in Background",
   "description": "For environments with approximately 3.5 million patrons, the system must run inactive patron report generation as a background operation so that producing the report does not require a foreground query to complete."
  },
  {
   "ref": "C055",
   "source_doc_id": "D09",
   "name": "Cache Report Results",
   "description": "The system must cache inactive patron report results so that results from the potentially slow activity query can be reused without rerunning the full query each time."
  },
  {
   "ref": "C056",
   "source_doc_id": "D10",
   "name": "Consortium Scale Support",
   "description": "The system must support a library consortium with 286 locations, 17 million annual circulations, and purchasing and processing of more than 900,000 items per year, while allowing searches and reports to run during open hours without disrupting other system functions."
  },
  {
   "ref": "C057",
   "source_doc_id": "D10",
   "name": "Supported Server Platforms",
   "description": "The system must operate on Linux or Solaris server environments."
  },
  {
   "ref": "C058",
   "source_doc_id": "D10",
   "name": "Client Access Options",
   "description": "The system must be accessible through a web browser or a Windows-compatible client."
  },
  {
   "ref": "C059",
   "source_doc_id": "D10",
   "name": "Supported Web Browsers",
   "description": "When accessed through a web browser, the system must support Microsoft Internet Explorer version 6.0 or later and Mozilla Firefox version 2.0 or later."
  },
  {
   "ref": "C060",
   "source_doc_id": "D10",
   "name": "Assistive Technology Access",
   "description": "The system must be accessible with screen-reading software, screen-magnification software, and other assistive technology programs intended to increase accessibility."
  },
  {
   "ref": "C061",
   "source_doc_id": "D10",
   "name": "Relational Database Backend",
   "description": "The system must use a fully relational database back end."
  },
  {
   "ref": "C062",
   "source_doc_id": "D10",
   "name": "Standards Compliant HTML",
   "description": "Web-based components must produce standards-compliant HTML output."
  },
  {
   "ref": "C063",
   "source_doc_id": "D10",
   "name": "Configuration Migration",
   "description": "The system must provide separate development and training environments and support migration of configurations from those environments to production."
  },
  {
   "ref": "C064",
   "source_doc_id": "D10",
   "name": "Role Based Access Control",
   "description": "The system must control user rights and privileges through security groups or roles that support access control for individuals, workgroups, and arbitrary staff groups."
  },
  {
   "ref": "C065",
   "source_doc_id": "D10",
   "name": "OPAC Feature Preservation",
   "description": "The Management Processes requirements must not constrain the functionality or features of the Online Public Access Catalog module."
  },
  {
   "ref": "C066",
   "source_doc_id": "D10",
   "name": "Management Data Specifications",
   "description": "The product must provide complete data specifications for authority, bibliographic, order, item, hold/request, and other records maintained or accessed by the Management Processes."
  },
  {
   "ref": "C067",
   "source_doc_id": "D10",
   "name": "Process Documentation",
   "description": "The product must provide thorough high-level descriptions of major processes, including bibliographic record import and export, validation of bibliographic records against internal and external authority sources, and standard reports."
  },
  {
   "ref": "C068",
   "source_doc_id": "D10",
   "name": "Online System Help",
   "description": "The system must provide online help in HTML that is hierarchical, cross-linked, and descriptive and illustrative of all system functions."
  },
  {
   "ref": "C069",
   "source_doc_id": "D10",
   "name": "Error Feedback",
   "description": "The system must provide thorough high-level error reporting and feedback and must provide low-level query-specific feedback through the front-end interface to Local and Global System Administrators."
  },
  {
   "ref": "C070",
   "source_doc_id": "D10",
   "name": "Staff Authentication",
   "description": "The system should support streamlined staff terminal login using either an employee card such as an RFID badge or individual username and password credentials, with username and password available as a fallback and card-based login not required."
  },
  {
   "ref": "C071",
   "source_doc_id": "D10",
   "name": "Report Template Management",
   "description": "System administrators should be able to create report templates that staff can run as-is or modify for individual needs without compromising result accuracy. Administrators should be able to restrict which filters and display fields staff may alter, such as allowing a call-number range or display-field changes while preventing changes that would expose deleted items."
  },
  {
   "ref": "C072",
   "source_doc_id": "D10",
   "name": "Report Permission Administration",
   "description": "The system should provide distinct, fine-grained and easily administered permissions controlling who may create and clone reports. System administrators should be able to create shared folders that allow or prohibit staff from running specific reports or running ad hoc reports against specified data sets."
  },
  {
   "ref": "C073",
   "source_doc_id": "D10",
   "name": "Multi-Record Query Designer",
   "description": "The system should provide a user-friendly query interface for bibliographic, item, patron, transaction, and financial records. Staff should be able to select query fields, choose values from picklists, choose regular expressions from a drop-down menu, and use Boolean operators, while administrators control staff access to tables and fields."
  },
  {
   "ref": "C074",
   "source_doc_id": "D10",
   "name": "Executive Reporting",
   "description": "The system should provide predefined reports for library boards and other external consumers, including basic statistics required by the Georgia Annual Report and Application for State Aid."
  },
  {
   "ref": "C075",
   "source_doc_id": "D10",
   "name": "Activity Cross Tabulation",
   "description": "Activity reports must show traffic and usage volume, including check-outs, check-ins, holds placed, and holds filled, with cross-tabulation by terminal, branch, library system, hour, patron age range, patron type, and patron location."
  },
  {
   "ref": "C076",
   "source_doc_id": "D10",
   "name": "Privacy Preserving Archives",
   "description": "The system must archive transactions in a form that protects patron privacy as defined by State Law while retaining useful demographic statistics."
  },
  {
   "ref": "C077",
   "source_doc_id": "D10",
   "name": "Periodic Management Reports",
   "description": "The system should provide periodic reports covering bibliographic records with holds; items not checked out for a configurable number of days; item-level holds; invalid item types; in-transit items with outstanding holds; items in transit beyond a configurable number of days; last copies; long call numbers; missing items; bibliographic records without item records; and patrons with invalid home libraries."
  },
  {
   "ref": "C078",
   "source_doc_id": "D10",
   "name": "Query Criteria Display",
   "description": "The system should display the query selections together with report results so users can see the criteria used to generate the report."
  },
  {
   "ref": "C079",
   "source_doc_id": "D10",
   "name": "Report Queue Visibility",
   "description": "Staff should be able to see the position of their report in the queue of reports waiting to run."
  },
  {
   "ref": "C080",
   "source_doc_id": "D10",
   "name": "Patron Behavior Statistics",
   "description": "The system should produce statistics for understanding and predicting patron behavior and material use, including average return speed for a particular book, likelihood of renewal, and the percentage of check-outs at a branch that are renewals."
  },
  {
   "ref": "C081",
   "source_doc_id": "D10",
   "name": "Anonymized Demographic Statistics",
   "description": "The system should produce demographic statistics such as transactions by geographic region and age range, using anonymized data from which information that could identify a patron has been deleted."
  },
  {
   "ref": "C082",
   "source_doc_id": "D10",
   "name": "Material Volume Reporting",
   "description": "The system must report the volume of material in a specified library at any point in time, based on new acquisitions, items on shelves, and items in circulation, with breakdowns such as total items, holds, adult fiction, and board books."
  },
  {
   "ref": "C083",
   "source_doc_id": "D10",
   "name": "Branch Capacity Interface",
   "description": "The system should provide an interface showing the capacity of all branches."
  },
  {
   "ref": "C084",
   "source_doc_id": "D10",
   "name": "Shelf Space Analysis",
   "description": "The system must compare, for each material genre and format, the percentage of total circulations, percentage of the collection, and percentage of total shelf space, with reports runnable per library and per system."
  },
  {
   "ref": "C085",
   "source_doc_id": "D10",
   "name": "Uncataloged Inventory Control",
   "description": "The system must control inventory of uncataloged materials such as paperback books and children's board books, support quick distribution with minimal branch labor, identify how such material is used, and count its transactions in circulation statistics and reports."
  },
  {
   "ref": "C086",
   "source_doc_id": "D10",
   "name": "Batch Item Transfers",
   "description": "The system must provide a utility for transferring batches of items between branches, including querying candidate materials, saving queries for reuse, manually selecting titles from results, changing selected item locations, moving items by changing the location field or generating pull lists, and reverting items to their original locations after a set period."
  },
  {
   "ref": "C087",
   "source_doc_id": "D10",
   "name": "Missing Damaged Reports",
   "description": "The system should provide reports of missing and damaged items by branch."
  },
  {
   "ref": "C088",
   "source_doc_id": "D10",
   "name": "In Transit Reporting",
   "description": "The system must generate a merged report of items in transit for more than a configurable number of days, showing results by branch and by system and combining transit-to and transit-from information for front-line staff."
  },
  {
   "ref": "C089",
   "source_doc_id": "D10",
   "name": "Item Purge Management",
   "description": "The system must provide utilities and reports for identifying item records to purge using customizable criteria, including items missing for more than a configurable number of months and items with a discard or weed status. It must also support status-conversion reports, last-copy reports, effective deletion of volume and copy entries, and identification of records without attached items."
  },
  {
   "ref": "C090",
   "source_doc_id": "D10",
   "name": "Deletion Tracking",
   "description": "The system must count and track deletions of records such as item and patron records by location and by system."
  },
  {
   "ref": "C091",
   "source_doc_id": "D10",
   "name": "Patron Characteristic Filtering",
   "description": "Queries and reports must be limitable or groupable by patron age range, ZIP code, county of residence, home branch, patron type, and preferred language."
  },
  {
   "ref": "C092",
   "source_doc_id": "D10",
   "name": "Inactive Patron Reporting",
   "description": "The system should generate a configurable report of patrons with no circulation or electronic activity during a configurable number of preceding days, with results configurable to system, home library, county, and similar organizational scopes."
  },
  {
   "ref": "C093",
   "source_doc_id": "D10",
   "name": "Transaction History Retention",
   "description": "The system must maintain transaction history for a configurable number of days and retain monthly and annual aggregate information indefinitely."
  },
  {
   "ref": "C094",
   "source_doc_id": "D10",
   "name": "Transaction Grouping",
   "description": "The system must group transactions by hour, terminal, branch, and system and support queries across all transaction types or a selected transaction type, including check-ins, check-outs, fines collected, and patron registrations."
  },
  {
   "ref": "C095",
   "source_doc_id": "D10",
   "name": "Check In Type Counts",
   "description": "The system must count check-ins individually and cumulatively by book drop, terminal, and user or self-service check-in."
  },
  {
   "ref": "C096",
   "source_doc_id": "D10",
   "name": "Check Out Type Counts",
   "description": "The system must count check-outs individually and cumulatively by staff check-out, self check-out, staff renewal, self-checkout renewal, online renewal, and OPAC renewal."
  },
  {
   "ref": "C097",
   "source_doc_id": "D10",
   "name": "Hold Placement Counts",
   "description": "The system must count hold requests and record how each hold was placed, including at a staff desk, at a public computer inside the library, or remotely."
  },
  {
   "ref": "C098",
   "source_doc_id": "D10",
   "name": "Transaction Summary Reports",
   "description": "The system must generate transaction reports for holds placed, holds filled, and check-outs by patron, library, selected groups of libraries, system, and county. Results must display check-outs and placed holds per patron and subtotal holds by type, including active, frozen, and frozen-until holds."
  },
  {
   "ref": "C099",
   "source_doc_id": "D10",
   "name": "Collection Value Reporting",
   "description": "The system must generate reports of item values based on item-record data for the entire collection or a portion of it, including values for items with a specified status, such as longoverdue, items in a specified collection such as children's DVDs, or the entire collection."
  },
  {
   "ref": "C100",
   "source_doc_id": "D10",
   "name": "Accounting Compliance",
   "description": "All reports and data archiving must comply with standard accounting practices and state, county, and municipal auditing requirements."
  },
  {
   "ref": "C101",
   "source_doc_id": "D10",
   "name": "Patron Financial Records",
   "description": "The system must attach fines, charges, waivers, and ecommerce transactions to patron and item records; track waived fines and payments by library; allow financial information to be updated easily; and support queries such as patron accounts with balances above a specified dollar amount."
  },
  {
   "ref": "C102",
   "source_doc_id": "D10",
   "name": "Financial Reporting",
   "description": "The system must provide financial reports showing patron account balances by patron, home library, and system; fines and charges by time period and charge type; fines waived by time period and branch; and payments by time period and payment method, including staff desk, self-check station, and OPAC."
  },
  {
   "ref": "C103",
   "source_doc_id": "D10",
   "name": "Payment Audit Ledger",
   "description": "The system must maintain a ledger of patron payments identifying the charges to which payments are applied, so that payments can be reconciled."
  },
  {
   "ref": "C104",
   "source_doc_id": "D10",
   "name": "Circulation Report Suite",
   "description": "The system must support circulation reports for check-in counts, checkout counts, items overdue by a specified number of days with daily, shelf-reading, and patron-contact information, circulation by circulation modifier, category, Dewey classification, shelving location, MARC data, patron county, patron home library, and age demographic, renewals, non-cataloged circulation, and total circulation with checkout, renewal, and non-cataloged breakdowns."
  },
  {
   "ref": "C105",
   "source_doc_id": "D10",
   "name": "Item Report Suite",
   "description": "The system must support item reports for items added, deleted, edited, or counted; items by fines-stopped reason, creation-date range, missing status, transit origin and destination, overdue or longoverdue status, total-use thresholds, last-copy deletion, claims returned, weeding data including last circulation and number of circulations, specified bibliographic content, collection age by call number or shelving location, collection price value by call number or shelving location, and items to be batch-converted from one status to another."
  },
  {
   "ref": "C106",
   "source_doc_id": "D10",
   "name": "Bibliographic Report Suite",
   "description": "The system must support bibliographic reports for record counts, edited-record counts, records added by user and library, records with no attached volumes, and records missing specified MARC fields."
  },
  {
   "ref": "C107",
   "source_doc_id": "D10",
   "name": "Patron Report Suite",
   "description": "The system must support patron reports for patron counts; additions by month; new patrons by demographic category; counts by age, county, home library, profile group, or survey answer; patrons by survey answer, expiration date, barred status, inactive status, note wording, or staff-account password-change date and account expiration."
  },
  {
   "ref": "C108",
   "source_doc_id": "D10",
   "name": "Hold Report Suite",
   "description": "The system must support hold reports for purchase alerts, items sent to and received for holds, IntraPINES loans by system and facility, unfilled holds, annual hold totals, and stale holds remaining on hold shelves beyond the permitted pickup period."
  },
  {
   "ref": "C109",
   "source_doc_id": "D10",
   "name": "In House Use Reports",
   "description": "The system must support reports for non-cataloged in-house use counts by month and cataloged in-house use counts."
  },
  {
   "ref": "C110",
   "source_doc_id": "D10",
   "name": "Transit Report Suite",
   "description": "The system must support reports of items in transit to a destination library and items in transit by sending library."
  },
  {
   "ref": "C111",
   "source_doc_id": "D10",
   "name": "Bills Report Suite",
   "description": "The system must support reports for bills currently owed by patrons, detailed payments received, detailed forgive/work/goods payments received, detailed voids, and aged debt."
  },
  {
   "ref": "C112",
   "source_doc_id": "D10",
   "name": "Report Interface Types",
   "description": "The reporting interface must provide canned reports that users can run immediately or recurrently, noncanned/on-demand reports with editable selection criteria and display options, and open-template reporting that allows selection of attributes associated with circulation, items, patrons, bills, and bibliographic records for filtering and display."
  },
  {
   "ref": "C113",
   "source_doc_id": "D10",
   "name": "Scheduled Canned Reports",
   "description": "Canned reports must include product-delivered templates that can run using yesterday's, last week's, last month's, or last year's data; users must be able to select multiple canned reports to run at the same time and view their output in one document."
  },
  {
   "ref": "C114",
   "source_doc_id": "D10",
   "name": "On Demand Report Runs",
   "description": "The system must provide on-demand reports based on preselected criteria for uses such as maintenance and collection development."
  },
  {
   "ref": "C115",
   "source_doc_id": "D10",
   "name": "Report Quick Access",
   "description": "The reporting interface must provide descriptions in pop-up boxes when users hover over canned-report or template titles, allow users to select data elements, and allow scheduling as soon as possible, hourly, daily, weekly, monthly, or yearly."
  },
  {
   "ref": "C116",
   "source_doc_id": "D10",
   "name": "Report Export Formats",
   "description": "Report output must be available in Excel, HTML, and CSV formats."
  },
  {
   "ref": "C117",
   "source_doc_id": "D10",
   "name": "Report Email Delivery",
   "description": "The system must allow users to enter email addresses for report delivery and should support an address book of regularly used addresses."
  },
  {
   "ref": "C118",
   "source_doc_id": "D10",
   "name": "Recurring Report Editing",
   "description": "Users must be able to edit recurring reports by adding or removing report selections and changing their email addresses."
  },
  {
   "ref": "C119",
   "source_doc_id": "D10",
   "name": "Comparative Report Output",
   "description": "The system must support report output with comparative columns such as last month's circulation, the previous month's circulation, percentage difference, the corresponding month of the previous year, and percentage difference between the previous month and the corresponding month of the previous year."
  },
  {
   "ref": "C120",
   "source_doc_id": "D10",
   "name": "Canned Report Administration",
   "description": "Authorized users must be able to add canned reports according to permission level and edit canned reports for display purposes, such as adding shelving location as a displayed field."
  },
  {
   "ref": "C121",
   "source_doc_id": "D10",
   "name": "Report Queue Prioritization",
   "description": "The system must allow certain report types to be prioritized so they appear ahead of resource-consuming reports in the execution queue."
  },
  {
   "ref": "C122",
   "source_doc_id": "D10",
   "name": "Item Use Metrics",
   "description": "Reports must provide total item-use counts and use counts broken down by usage date ranges, such as fiscal-year or monthly counts, and must support total circulation including checkouts, renewals, and non-cataloged circulation with a breakdown by circulation type."
  },
  {
   "ref": "C123",
   "source_doc_id": "D10",
   "name": "File Based Report Filtering",
   "description": "The system must allow users to upload a text file containing values such as barcodes or TCNs and use those values to filter a report."
  },
  {
   "ref": "C124",
   "source_doc_id": "D10",
   "name": "Notice Reporting",
   "description": "The system must support reports for pre-overdue notices, overdue notices, and holds notices sent."
  },
  {
   "ref": "C125",
   "source_doc_id": "D10",
   "name": "Pivot Table Output",
   "description": "The reporting system must provide pivot-table output."
  },
  {
   "ref": "C126",
   "source_doc_id": "D10",
   "name": "Report Output Validation",
   "description": "Report output must be tested and proven accurate and dependable."
  },
  {
   "ref": "C127",
   "source_doc_id": "D10",
   "name": "Report Cancellation",
   "description": "Users must be able to cancel a report that is scheduled to run or is currently running."
  },
  {
   "ref": "C128",
   "source_doc_id": "D10",
   "name": "Null Value Inclusion",
   "description": "Report results must include all null and blank fields regardless of the fields being filtered or displayed."
  },
  {
   "ref": "C129",
   "source_doc_id": "D10",
   "name": "Real Time Reporting",
   "description": "The system must support real-time reporting."
  },
  {
   "ref": "C130",
   "source_doc_id": "D10",
   "name": "Historical Reporting Warehouse",
   "description": "The system must support historical reporting through a reporting warehouse so data can be acquired for a specified date or date range."
  },
  {
   "ref": "C131",
   "source_doc_id": "D10",
   "name": "Report Criteria Transparency",
   "description": "The system must clearly define selection criteria and include the selected date criteria and report name at the top or bottom of report results."
  },
  {
   "ref": "C132",
   "source_doc_id": "D10",
   "name": "Survey Name Filtering",
   "description": "Users must be able to select a survey by survey name for filtering without entering its survey identifier."
  },
  {
   "ref": "C133",
   "source_doc_id": "D10",
   "name": "Deleted Last Copy Reporting",
   "description": "The system must provide reports identifying deleted items that were the last copy owned by a library system or facility, to support WorldCat updates."
  },
  {
   "ref": "C134",
   "source_doc_id": "D10",
   "name": "MARC Row Consolidation",
   "description": "The system must be able to retrieve MARC record fields and display them on a single row of report data."
  },
  {
   "ref": "C135",
   "source_doc_id": "D10",
   "name": "Workstation Transaction Reporting",
   "description": "The system must support reports for transactions occurring on a specified date and time, at a specified workstation, or performed by a specified staff member."
  },
  {
   "ref": "C136",
   "source_doc_id": "D11",
   "name": "Generate Item Value Reports",
   "description": "The system must generate reports showing the value of items, using the purchase price or other value data in item records, for the entire collection or a selected portion. The report must support selections such as all items with status \"longoverdue\", all DVDs in the children's collection, and the entire collection."
  },
  {
   "ref": "C137",
   "source_doc_id": "D11",
   "name": "Compliant Financial Reporting",
   "description": "The system's financial reports must comply with standard accounting practices and state, county, and municipal auditing requirements."
  },
  {
   "ref": "C138",
   "source_doc_id": "D11",
   "name": "Enforce Data Retention",
   "description": "The system must archive financial data in accordance with state and local requirements and enforce retention policies, including retaining applicable audit data for seven years."
  },
  {
   "ref": "C139",
   "source_doc_id": "D11",
   "name": "Associate Financial Records",
   "description": "The system must associate fines, charges, waived fines, payments, and ecommerce transactions with the relevant patron and item records, and support joining patron and item financial data when querying financial information."
  },
  {
   "ref": "C140",
   "source_doc_id": "D11",
   "name": "Find High-Balance Accounts",
   "description": "Staff must be able to query patron accounts with balances greater than a user-specified dollar amount so that accounts requiring attention can be identified."
  },
  {
   "ref": "C141",
   "source_doc_id": "D11",
   "name": "Update Payment Information",
   "description": "The system must allow financial information to be updated easily and must reflect a patron payment made at a front desk immediately."
  },
  {
   "ref": "C142",
   "source_doc_id": "D11",
   "name": "Report Patron Balances",
   "description": "The system must provide financial reports showing patron account balances by individual patron, home library, and the library system."
  },
  {
   "ref": "C143",
   "source_doc_id": "D11",
   "name": "Report Accrued Charges",
   "description": "The system must provide reports of fines and charges accrued for selectable time periods, including the last 12 months, year to date, and the last month, and by charge type such as overdue fines, damaged-item charges, and lost-item charges."
  },
  {
   "ref": "C144",
   "source_doc_id": "D11",
   "name": "Report Waived Fines",
   "description": "The system must provide reports of fines waived by selectable time period and by branch or library, so waived-fine activity can be tracked against each library's budget."
  },
  {
   "ref": "C145",
   "source_doc_id": "D11",
   "name": "Report Collected Payments",
   "description": "The system must provide reports of payments made for selectable time periods, payment methods, and collecting libraries or branches. Payment methods must include channels such as the staff desk, self-check station, and OPAC, and types such as cash, credit card, and check."
  },
  {
   "ref": "C146",
   "source_doc_id": "D11",
   "name": "Maintain Payment Audit Ledger",
   "description": "The system must maintain a ledger of patron payments that identifies the specific charge or charges to which each payment was applied, allowing finance staff to trace every payment and reconcile accounts."
  },
  {
   "ref": "C147",
   "source_doc_id": "D12",
   "name": "Design Queries Across Records",
   "description": "The system must provide a user-friendly query-design interface that works across all record types and lets staff select query fields, choose values from picklists, select regular expressions from a dropdown, and apply Boolean operators."
  },
  {
   "ref": "C148",
   "source_doc_id": "D12",
   "name": "Control Query Tool Access",
   "description": "The system must let administrators control which users can access the query-design tool."
  },
  {
   "ref": "C149",
   "source_doc_id": "D12",
   "name": "Create Shared Report Templates",
   "description": "The system must let administrators create report templates that are available to staff, so users requesting the same report run it with consistent criteria."
  },
  {
   "ref": "C150",
   "source_doc_id": "D12",
   "name": "Run And Modify Templates",
   "description": "The system must let staff run report templates as-is or modify them within administrator-defined controls, including limits on which filters and display fields may be changed; permitted changes must not compromise the template's intended results, such as allowing a weeding report to change its call-number range or display fields without allowing it to display deleted items."
  },
  {
   "ref": "C151",
   "source_doc_id": "D12",
   "name": "Clone Existing Reports",
   "description": "The system must let authorized users clone an existing report template to create a new report variant distinct from the original template."
  },
  {
   "ref": "C152",
   "source_doc_id": "D12",
   "name": "Manage Report Permissions",
   "description": "The system must provide distinct, fine-grained permission levels that control who can create and clone reports and which staff can run specific reports or ad hoc reports against specified sets of data; administrators must be able to administer these permissions through shared folders that allow or disallow the relevant access."
  },
  {
   "ref": "C153",
   "source_doc_id": "D12",
   "name": "Apply Role-Based Permissions",
   "description": "The system must update a user's report permissions automatically when the user's role changes, such as changing the user from Staff to Manager."
  },
  {
   "ref": "C154",
   "source_doc_id": "D12",
   "name": "Provide Board Reports",
   "description": "The system must provide predefined reports for library boards covering basic statistics required by the Georgia Annual Report and activity statistics for traffic and volume of use, including checkouts, check-ins, holds placed, and holds filled; the activity data must support cross-tabulation by terminal, branch, system, hour, age range, patron type, and patron location."
  },
  {
   "ref": "C155",
   "source_doc_id": "D12",
   "name": "Archive Private Transactions",
   "description": "The system must retain transaction data for the period required by State law, including the unspecified period represented as X years, while protecting patron privacy by not retaining personally identifiable information and preserving data sufficient to produce useful demographic statistics."
  },
  {
   "ref": "C156",
   "source_doc_id": "D12",
   "name": "Show Query Selections",
   "description": "The system must display the query selections or criteria together with the query results."
  },
  {
   "ref": "C157",
   "source_doc_id": "D12",
   "name": "Show Report Queue Position",
   "description": "The system must show staff whether a submitted report is in the queue, how many reports are ahead of it, when it was submitted, and its status as waiting, running, completed, or failed."
  },
  {
   "ref": "C158",
   "source_doc_id": "D12",
   "name": "Prioritize Reports In Queue",
   "description": "The system must allow authorized report prioritization so that important reports, such as a director's board report, can move ahead of lower-priority reports such as a staff member's ad hoc query."
  },
  {
   "ref": "C159",
   "source_doc_id": "D13",
   "name": "Support Streamlined Staff Login",
   "description": "The system must support an optional streamlined staff login method, such as swiping an employee ID badge, while also supporting traditional individual username-and-password login as a fallback for staff without ID cards or branches without card-reader infrastructure."
  },
  {
   "ref": "C160",
   "source_doc_id": "D13",
   "name": "Authenticate Individual Staff Members",
   "description": "Regardless of the login method used, the system must individually authenticate the staff member and record which staff member is logged in so that staff activity can be associated with the correct person for audit purposes; a card swipe must not bypass individual authentication."
  },
  {
   "ref": "C161",
   "source_doc_id": "D13",
   "name": "Control Access By Staff Roles",
   "description": "The system must determine staff permissions from assigned security groups or roles and provide access control for individual staff members, workgroups, and arbitrary staff groups. Roles must support different permission levels, including front-desk staff with access to basic reports and limited filters, department heads who can create and modify templates, and system administrators with full access to reports and permissions."
  },
  {
   "ref": "C162",
   "source_doc_id": "D13",
   "name": "Administer Roles And Permissions",
   "description": "Administrators must be able to create and manage security groups or roles and assign them to staff members. Changing a staff member's permissions must be achievable by changing the person's role assignment rather than modifying individual permissions."
  },
  {
   "ref": "C163",
   "source_doc_id": "D14",
   "name": "Circulation By Modifier",
   "description": "The reporting system must provide a circulation-count report grouped by circulation modifier, including the modifier associated with each circulation transaction."
  },
  {
   "ref": "C164",
   "source_doc_id": "D14",
   "name": "Circulation By Dewey",
   "description": "The reporting system must provide a circulation-count report grouped by Dewey classification."
  },
  {
   "ref": "C165",
   "source_doc_id": "D14",
   "name": "Circulation By MARC Fields",
   "description": "The reporting system must provide a circulation-count report grouped or filtered by specified MARC fields."
  },
  {
   "ref": "C166",
   "source_doc_id": "D14",
   "name": "Circulation By County",
   "description": "The reporting system must provide circulation counts by circulation location with a breakdown by patron county."
  },
  {
   "ref": "C167",
   "source_doc_id": "D14",
   "name": "Circulation By Age",
   "description": "The reporting system must provide circulation counts by patron age demographic."
  },
  {
   "ref": "C168",
   "source_doc_id": "D14",
   "name": "Items Edited Report",
   "description": "The reporting system must provide a report counting items edited during a specified reporting period."
  },
  {
   "ref": "C169",
   "source_doc_id": "D14",
   "name": "Fines Stopped Reasons",
   "description": "The reporting system must provide a list of items grouped or filtered by the reason that fines were stopped."
  },
  {
   "ref": "C170",
   "source_doc_id": "D14",
   "name": "Overdue Items Contacts",
   "description": "The reporting system must provide a report of items overdue by a specified number of days and include the associated patron contact information."
  },
  {
   "ref": "C171",
   "source_doc_id": "D14",
   "name": "Items By Use Count",
   "description": "The reporting system must provide a list of items having a specified total use count."
  },
  {
   "ref": "C172",
   "source_doc_id": "D14",
   "name": "Last Copy Report",
   "description": "The reporting system must provide an enhanced last-copy report identifying items that are the last copy of their bibliographic work or collection grouping."
  },
  {
   "ref": "C173",
   "source_doc_id": "D14",
   "name": "Items By Creation Date",
   "description": "The reporting system must provide a list of items created within a specified date range."
  },
  {
   "ref": "C174",
   "source_doc_id": "D14",
   "name": "Claims Returned Report",
   "description": "The reporting system must provide a report of items recorded as claims returned."
  },
  {
   "ref": "C175",
   "source_doc_id": "D14",
   "name": "Weeding Circulation Report",
   "description": "The reporting system must provide a weeding report that includes each item's date of last circulation."
  },
  {
   "ref": "C176",
   "source_doc_id": "D14",
   "name": "Collection Age By Call Number",
   "description": "The reporting system must provide the age of the collection broken down by call number."
  },
  {
   "ref": "C177",
   "source_doc_id": "D14",
   "name": "Collection Value By Call Number",
   "description": "The reporting system must provide the price value of the collection broken down by call number."
  },
  {
   "ref": "C178",
   "source_doc_id": "D14",
   "name": "Bibliographic Edits Report",
   "description": "The reporting system must provide a report counting bibliographic records edited during a specified reporting period."
  },
  {
   "ref": "C179",
   "source_doc_id": "D14",
   "name": "Bibliographic Additions Report",
   "description": "The reporting system must provide a report counting bibliographic records added by user and by library."
  },
  {
   "ref": "C180",
   "source_doc_id": "D14",
   "name": "Missing MARC Fields",
   "description": "The reporting system must provide a report identifying bibliographic records missing specified MARC fields."
  },
  {
   "ref": "C181",
   "source_doc_id": "D14",
   "name": "Patron Count By Age",
   "description": "The reporting system must provide patron counts by age demographic."
  },
  {
   "ref": "C182",
   "source_doc_id": "D14",
   "name": "Patron Count By County",
   "description": "The reporting system must provide patron counts by county."
  },
  {
   "ref": "C183",
   "source_doc_id": "D14",
   "name": "Patron Geographic Counts",
   "description": "The reporting system must provide patron counts broken down by county, city, and ZIP code."
  },
  {
   "ref": "C184",
   "source_doc_id": "D14",
   "name": "Voter Survey Responses",
   "description": "The reporting system must provide a report of voter survey responses."
  },
  {
   "ref": "C185",
   "source_doc_id": "D14",
   "name": "Inactive Patrons Report",
   "description": "The reporting system must provide a list of patrons whose status is inactive."
  },
  {
   "ref": "C186",
   "source_doc_id": "D14",
   "name": "Staff Password Change Dates",
   "description": "The reporting system must provide a report of staff accounts including the date of each account's last password change."
  },
  {
   "ref": "C187",
   "source_doc_id": "D14",
   "name": "Holds Purchase Alert",
   "description": "The reporting system must provide a holds purchase alert report identifying hold activity that indicates a potential purchasing need."
  },
  {
   "ref": "C188",
   "source_doc_id": "D14",
   "name": "Unfilled Holds Report",
   "description": "The reporting system must provide a report of unfilled hold requests."
  },
  {
   "ref": "C189",
   "source_doc_id": "D14",
   "name": "Stale Holds Report",
   "description": "The reporting system must provide a report of stale hold requests."
  },
  {
   "ref": "C190",
   "source_doc_id": "D14",
   "name": "Detailed Aged Debt",
   "description": "The reporting system must provide an enhanced aged-debt report with detailed debt information for patrons and the applicable aging periods."
  },
  {
   "ref": "C191",
   "source_doc_id": "D14",
   "name": "Report Queue Visibility",
   "description": "The reporting system must show staff the queue position and current status of their submitted reports."
  },
  {
   "ref": "C192",
   "source_doc_id": "D14",
   "name": "Report Prioritization",
   "description": "The reporting system must allow authorized users or processes to prioritize selected types of reports for execution."
  },
  {
   "ref": "C193",
   "source_doc_id": "D14",
   "name": "Cancel Running Reports",
   "description": "The reporting system must allow a user to cancel a report that is currently running."
  },
  {
   "ref": "C194",
   "source_doc_id": "D14",
   "name": "Pivot Table Output",
   "description": "The reporting system must produce report results in pivot-table format."
  },
  {
   "ref": "C195",
   "source_doc_id": "D14",
   "name": "Real-Time Reporting",
   "description": "The reporting system must support reports that use current data in real time rather than only processing a static or delayed reporting dataset."
  },
  {
   "ref": "C196",
   "source_doc_id": "D14",
   "name": "Historical Reporting Warehouse",
   "description": "The system must provide a historical reporting warehouse that preserves data needed for reporting on past states and time periods."
  },
  {
   "ref": "C197",
   "source_doc_id": "D14",
   "name": "Report Scheduling Options",
   "description": "The reporting system must allow a report to be run ASAP or scheduled hourly, daily, weekly, monthly, or yearly."
  },
  {
   "ref": "C198",
   "source_doc_id": "D14",
   "name": "Report Email Delivery",
   "description": "The reporting system must deliver report results by email in addition to making them available through the web interface."
  },
  {
   "ref": "C199",
   "source_doc_id": "D14",
   "name": "Report Delivery Address Book",
   "description": "The reporting system must provide an address book for selecting recipients for report delivery."
  },
  {
   "ref": "C200",
   "source_doc_id": "D14",
   "name": "Text File Filtering",
   "description": "The reporting system must allow users to upload text files containing values such as barcodes or TCNs and use those values as report-filtering criteria."
  },
  {
   "ref": "C201",
   "source_doc_id": "D14",
   "name": "Selection Criteria Results",
   "description": "The reporting system must display the selection criteria used to generate a report within the report results."
  },
  {
   "ref": "C202",
   "source_doc_id": "D14",
   "name": "Canned Display Options",
   "description": "The reporting system must allow users to edit the display options of canned reports."
  },
  {
   "ref": "C203",
   "source_doc_id": "D14",
   "name": "Report Quick Access",
   "description": "The reporting system must provide a quick-access interface for reports with pop-up descriptions."
  },
  {
   "ref": "C204",
   "source_doc_id": "D14",
   "name": "Report Title Tooltips",
   "description": "The reporting system must provide hover tooltips describing report titles."
  },
  {
   "ref": "C205",
   "source_doc_id": "D14",
   "name": "Reporting Database Replica",
   "description": "The system must provide a separate reporting database or replica so reporting workloads are separated from the production database."
  },
  {
   "ref": "C206",
   "source_doc_id": "D14",
   "name": "Background Report Processing",
   "description": "The reporting system must process long-running reports in the background without requiring the user interface to remain occupied by the report execution."
  },
  {
   "ref": "C207",
   "source_doc_id": "D14",
   "name": "Report Template Management",
   "description": "The reporting system must provide management of report templates, including storing and maintaining reusable report definitions."
  },
  {
   "ref": "C208",
   "source_doc_id": "D14",
   "name": "Fine-Grained Report Permissions",
   "description": "The reporting system must provide fine-grained report permissions that control who can create reports, run reports, access reports, use specific filters, and access shared report resources."
  },
  {
   "ref": "C209",
   "source_doc_id": "D14",
   "name": "Reporting Environment Separation",
   "description": "The product must provide separate development and training environments for reporting functionality."
  },
  {
   "ref": "C210",
   "source_doc_id": "D14",
   "name": "Environment Configuration Migration",
   "description": "The reporting system must support migration of reporting configuration between environments."
  },
  {
   "ref": "C211",
   "source_doc_id": "D14",
   "name": "Accessible Report Interface",
   "description": "The report interface must provide accessibility support sufficient for staff using the reporting system, including compliance with applicable accessibility requirements."
  },
  {
   "ref": "C212",
   "source_doc_id": "D14",
   "name": "Integrated Report Help",
   "description": "The reporting system must provide an online help system integrated with the report interface."
  },
  {
   "ref": "C213",
   "source_doc_id": "D14",
   "name": "Three Reporting Interfaces",
   "description": "The reporting system must provide separate canned-report, on-demand-report, and open-template-reporting interfaces."
  },
  {
   "ref": "C214",
   "source_doc_id": "D14",
   "name": "Snapshot Bills Reporting",
   "description": "The reporting system must provide a snapshot bills report that can report bill information as it existed at a point in the past."
  },
  {
   "ref": "C215",
   "source_doc_id": "D14",
   "name": "Separate Last Edit Date",
   "description": "The reporting system must provide a last-edit date that does not represent or incorporate the date of the item's last circulation."
  },
  {
   "ref": "C216",
   "source_doc_id": "D14",
   "name": "Last Circulation Date",
   "description": "The reporting system must expose the date of an item's last circulation as a separate reportable field."
  },
  {
   "ref": "C217",
   "source_doc_id": "D14",
   "name": "Checkin Date Excluding Renewals",
   "description": "The reporting system must provide check-in date and time separately from renewal timestamps, so reports can identify check-ins without treating renewals as check-ins."
  },
  {
   "ref": "C218",
   "source_doc_id": "D14",
   "name": "Preserve Null And Blank Fields",
   "description": "The reporting system must include null and blank fields in report results rather than filtering them out."
  },
  {
   "ref": "C219",
   "source_doc_id": "D14",
   "name": "Multiple Report Formats",
   "description": "The reporting system must provide report output in multiple formats, including CSV, HTML, and an Excel-compatible format."
  },
  {
   "ref": "C220",
   "source_doc_id": "D15",
   "name": "Track Uncataloged Materials",
   "description": "The system must track uncataloged paperback books, children's board books, and other material as inventory before individual catalog records are available, while supporting rapid distribution with minimal branch labor and enabling staff to identify how the material is being used."
  },
  {
   "ref": "C221",
   "source_doc_id": "D15",
   "name": "Count Uncataloged Transactions",
   "description": "The system must count transactions involving uncataloged material and include those transactions in circulation statistics and reports."
  },
  {
   "ref": "C222",
   "source_doc_id": "D15",
   "name": "Query Transfer Candidates",
   "description": "The item transfer utility must allow staff to query for candidate materials, such as all items in the children's section that have not circulated in six months, for transfer between branches or to mobile and outreach collections."
  },
  {
   "ref": "C223",
   "source_doc_id": "D15",
   "name": "Save Transfer Queries",
   "description": "The item transfer utility must allow staff to save candidate-material queries for repeated use, including monthly reuse."
  },
  {
   "ref": "C224",
   "source_doc_id": "D15",
   "name": "Select Transfer Items",
   "description": "The item transfer utility must allow staff to manually select individual titles from query results when a targeted transfer is required."
  },
  {
   "ref": "C225",
   "source_doc_id": "D15",
   "name": "Change Item Locations",
   "description": "The item transfer utility must allow staff to change the records of selected items so that the items move to a new location."
  },
  {
   "ref": "C226",
   "source_doc_id": "D15",
   "name": "Revert Item Locations",
   "description": "The item transfer utility must provide a mechanism to return transferred items to their original location after a defined period, such as when a mobile library returns to its base."
  },
  {
   "ref": "C227",
   "source_doc_id": "D15",
   "name": "Report Missing Damaged Items",
   "description": "The system must provide a report showing all missing and damaged items for each branch so collection management staff can monitor collection health and identify patterns of loss or damage."
  },
  {
   "ref": "C228",
   "source_doc_id": "D15",
   "name": "Report Overdue Transit Items",
   "description": "The system must provide one report combining transit-to and transit-from items that have remained in transit longer than a configurable number of days, with results available per branch and for the entire system."
  },
  {
   "ref": "C229",
   "source_doc_id": "D15",
   "name": "Identify Purge Candidates",
   "description": "The system must provide a weeding report that identifies items for purging using customizable criteria, including items that have been in status \"missing\" longer than a specified number of months and items with status \"discard/weed.\""
  },
  {
   "ref": "C230",
   "source_doc_id": "D15",
   "name": "Batch Change Item Status",
   "description": "The system must provide a report or operation that assists staff in converting selected items from one status to another in batch, including changing 100 items from \"missing\" to \"discard/weed.\""
  },
  {
   "ref": "C231",
   "source_doc_id": "D15",
   "name": "Report Last System Copies",
   "description": "The system must provide a report identifying the last copies held by a library system so catalogers can check and edit corresponding WorldCat entries before deleting or otherwise altering a rare or final copy."
  },
  {
   "ref": "C232",
   "source_doc_id": "D15",
   "name": "Delete Orphaned Records",
   "description": "The system must provide a quick, effective method for deleting volume entries together with their copy entries and for deleting records that have no items attached, to support cleanup of orphaned catalog records."
  },
  {
   "ref": "C233",
   "source_doc_id": "D15",
   "name": "Track Record Deletions",
   "description": "The system must count and track record deletions by location and by library system, including the reason for each deletion, to support auditing and troubleshooting."
  },
  {
   "ref": "C234",
   "source_doc_id": "D15",
   "name": "Report Shelf Space Allocation",
   "description": "The system must provide a shelf space report that compares, for each genre and format, the percentage of total circulations, the percentage of the collection, and the percentage of total shelf space, so collection managers can allocate resources."
  },
  {
   "ref": "C235",
   "source_doc_id": "D15",
   "name": "Report Material Volumes",
   "description": "The system must provide a material volume report covering acquisitions, items on shelf, and items in circulation, broken down by categories such as total items, holds, adult fiction, and board books."
  },
  {
   "ref": "C236",
   "source_doc_id": "D15",
   "name": "Provide Data Quality Reports",
   "description": "The system must provide data quality reports identifying items with invalid item types, items with excessively long call numbers, and bibliographic records with no item records, so staff can maintain catalog data integrity."
  },
  {
   "ref": "C237",
   "source_doc_id": "D15",
   "name": "Display Item Edit Dates",
   "description": "Reports must show the date an item was last edited, where the date changes only when the item is edited and does not treat the last circulation as an edit; the edit date must not be combined with the last circulation date."
  },
  {
   "ref": "C238",
   "source_doc_id": "D16",
   "name": "Linux Solaris Compatibility",
   "description": "The reporting system must operate on both Red Hat Enterprise Linux 5 and Solaris 10 on SPARC hardware, including the primary and disaster-recovery/reporting server environments."
  },
  {
   "ref": "C239",
   "source_doc_id": "D16",
   "name": "Open-Hours Report Processing",
   "description": "The system must process searches and reports during library open hours without disrupting circulation or other system functions, including avoiding database contention from complex reports; background queuing or read-only reporting replicas may be used to achieve this."
  },
  {
   "ref": "C240",
   "source_doc_id": "D16",
   "name": "Legacy Browser Support",
   "description": "The system must support Microsoft Internet Explorer 6.0 and later and Firefox 2.0 and later so that libraries using the existing browser installations can run the reporting system."
  },
  {
   "ref": "C241",
   "source_doc_id": "D16",
   "name": "Section 508 Accessibility",
   "description": "The system must comply with Section 508 and support staff using screen readers such as JAWS and NVDA, screen magnification software such as ZoomText, and other assistive technologies. Its HTML output must use alt tags, ARIA labels, semantic structure, and standards-compliant HTML."
  },
  {
   "ref": "C242",
   "source_doc_id": "D16",
   "name": "Relational Database Integration",
   "description": "The reporting system must work with PINES's fully relational PostgreSQL database structure, support complex joins, and use the main relational database rather than requiring a denormalized reporting schema that can create synchronization issues."
  },
  {
   "ref": "C243",
   "source_doc_id": "D16",
   "name": "Role-Based Access Control",
   "description": "The system must control permissions through security groups and/or roles for individuals, workgroups, and arbitrary staff groups. It must support the Patron, Staff, Local Admin, and Global Admin access levels, with Local Admins able to run reports and configure local settings and Global Admins having full system access."
  },
  {
   "ref": "C244",
   "source_doc_id": "D16",
   "name": "Simple Role Administration",
   "description": "Administrators must be able to change a user's permissions by changing the user's role assignment, with roles being easy to administer."
  },
  {
   "ref": "C245",
   "source_doc_id": "D16",
   "name": "Separate Development Environment",
   "description": "The product must provide a development environment where developers can test new reports without affecting the production environment."
  },
  {
   "ref": "C246",
   "source_doc_id": "D16",
   "name": "Separate Training Environment",
   "description": "The product must provide a training environment where new staff can practice running reports without affecting production or making operational mistakes."
  },
  {
   "ref": "C247",
   "source_doc_id": "D16",
   "name": "Configuration Migration",
   "description": "The system must provide export and import functionality to migrate report templates, permission settings, and other configuration from development or training environments into production."
  },
  {
   "ref": "C248",
   "source_doc_id": "D16",
   "name": "OPAC Isolation",
   "description": "The management reporting system must remain separate from the OPAC so that reporting activity, including large queries, does not constrain or slow the OPAC and patrons retain fast, responsive catalog access."
  },
  {
   "ref": "C249",
   "source_doc_id": "D16",
   "name": "Searchable Hierarchical Help",
   "description": "The system must provide online HTML help for staff that is hierarchical, cross-linked, searchable, and easy to navigate, including guidance on how to run reports."
  },
  {
   "ref": "C250",
   "source_doc_id": "D17",
   "name": "Collection Use Analysis",
   "description": "The reports interface must enable library managers, administrators, and staff to analyze library collections and how patrons use them for planning, evaluation, and oversight."
  },
  {
   "ref": "C251",
   "source_doc_id": "D17",
   "name": "Branch Capacity Analysis",
   "description": "The reports interface must enable authorized library managers and administrators to analyze branch capacity and determine the optimal distribution of the library collection across branches."
  },
  {
   "ref": "C252",
   "source_doc_id": "D17",
   "name": "Patron Demographics Analysis",
   "description": "The reports interface must enable authorized library managers and staff to analyze patron demographics and interests to support planning and evaluation of library services."
  },
  {
   "ref": "C253",
   "source_doc_id": "D17",
   "name": "Staff Workflow Analysis",
   "description": "The reports interface must enable authorized managers and supervisors to analyze staff productivity and workflow for oversight and service planning."
  },
  {
   "ref": "C254",
   "source_doc_id": "D17",
   "name": "Financial Transaction Verification",
   "description": "The system must provide reports or analysis capabilities that allow authorized library staff and managers to track and verify financial transactions."
  },
  {
   "ref": "C255",
   "source_doc_id": "D17",
   "name": "Library Report Templates",
   "description": "The product must provide report templates needed by all PINES member libraries for their management reporting activities."
  },
  {
   "ref": "C256",
   "source_doc_id": "D17",
   "name": "Management Reporting Scope",
   "description": "The reports functionality must support management processes used by library managers, administrators, and staff for planning, evaluation, and oversight, rather than day-to-day patron-facing functions handled through the OPAC and circulation client."
  },
  {
   "ref": "C257",
   "source_doc_id": "D17",
   "name": "Consortium Statistical Reporting",
   "description": "The system must enable the Global System Administrator, representing the PINES central IT team, to generate statistical reports for the PINES consortium as a whole."
  },
  {
   "ref": "C258",
   "source_doc_id": "D18",
   "name": "Consortium-Scale Operations",
   "description": "The management processes must support a library consortium with 286 locations, 17 million annual circulations, and purchasing and processing of more than 900,000 items per year."
  },
  {
   "ref": "C259",
   "source_doc_id": "D18",
   "name": "Background Report Processing",
   "description": "The system must process searches and reports in the background or through a queue so that report generation during open or peak hours does not slow down circulation-client operations or other system functions."
  },
  {
   "ref": "C260",
   "source_doc_id": "D18",
   "name": "Linux Solaris Server Support",
   "description": "The management processes must operate on either a Linux or Solaris server."
  },
  {
   "ref": "C261",
   "source_doc_id": "D18",
   "name": "Browser Client Access",
   "description": "The management processes must be accessible through a web browser or a Windows-compatible client. Browser-based access must support Microsoft Internet Explorer version 6.0 or later and Mozilla Firefox version 2.0 or later."
  },
  {
   "ref": "C262",
   "source_doc_id": "D18",
   "name": "Assistive Technology Access",
   "description": "The management processes must be accessible using screen-reading, screen-magnification, and other accessibility software, including JAWS, NVDA, and ZoomText, and must satisfy Section 508 requirements."
  },
  {
   "ref": "C263",
   "source_doc_id": "D18",
   "name": "Inventory Capacity Reports",
   "description": "The system must provide inventory and capacity reports for library staff who use them to monitor collections and operational capacity."
  },
  {
   "ref": "C264",
   "source_doc_id": "D18",
   "name": "Financial Reports",
   "description": "The system must provide financial reports for library directors and other users who need director-level financial information."
  },
  {
   "ref": "C265",
   "source_doc_id": "D18",
   "name": "Cross-Branch Comparisons",
   "description": "The system must provide reports that compare relevant library data across branches so library management can evaluate branches against one another."
  },
  {
   "ref": "C266",
   "source_doc_id": "D18",
   "name": "Report Queue Visibility",
   "description": "The system must allow users to view the status and contents of the report-processing queue so they can monitor reports awaiting or undergoing processing."
  },
  {
   "ref": "C267",
   "source_doc_id": "D18",
   "name": "Executive Report Definitions",
   "description": "The system must provide predefined reports for boards and executive users, supporting recurring executive-level reporting needs."
  },
  {
   "ref": "C268",
   "source_doc_id": "D18",
   "name": "Data Quality Reports",
   "description": "The system must provide data quality reports that help library staff identify and assess problems in the system's data."
  },
  {
   "ref": "C269",
   "source_doc_id": "D18",
   "name": "Card Swipe Login",
   "description": "The system must support staff login using a card swipe so staff can authenticate without relying solely on manually entered credentials."
  },
  {
   "ref": "C270",
   "source_doc_id": "D18",
   "name": "In-Transit Item Reports",
   "description": "The system must provide reports on items in transit so library staff can coordinate delivery between locations."
  },
  {
   "ref": "C271",
   "source_doc_id": "D18",
   "name": "Missing Damaged Item Reports",
   "description": "The system must provide reports of missing and damaged items, with results available per branch so branch staff can manage local item problems."
  },
  {
   "ref": "C272",
   "source_doc_id": "D18",
   "name": "Weeding Reports",
   "description": "The system must provide weeding reports that help library staff identify materials for collection-weeding activities."
  },
  {
   "ref": "C273",
   "source_doc_id": "D18",
   "name": "Shelf Space Utilization",
   "description": "The system must provide reports showing shelf-space utilization so library staff can assess and plan physical collection capacity."
  },
  {
   "ref": "C274",
   "source_doc_id": "D18",
   "name": "Demographic Analysis Reports",
   "description": "The system must provide demographic analysis for library staff planning programs and services."
  },
  {
   "ref": "C275",
   "source_doc_id": "D18",
   "name": "Relational Database Backend",
   "description": "The management processes must use a fully relational database backend and operate correctly with the relational data structure used by the reporting layer."
  },
  {
   "ref": "C276",
   "source_doc_id": "D18",
   "name": "Standards-Compliant HTML",
   "description": "The system must produce valid, standards-compliant HTML for report displays, the help system, and web-based user-interface components."
  },
  {
   "ref": "C277",
   "source_doc_id": "D18",
   "name": "Configuration Migration Environments",
   "description": "The product must provide separate development and training environments and support migrating configurations, including report templates, between those environments and production through export and import."
  },
  {
   "ref": "C278",
   "source_doc_id": "D18",
   "name": "Role-Based Access Control",
   "description": "The system must control user rights and privileges through security groups or roles, with access control applicable to individuals, workgroups, and arbitrary staff groups."
  },
  {
   "ref": "C279",
   "source_doc_id": "D18",
   "name": "OPAC Functionality Preservation",
   "description": "Changes and functionality in the management processes must not constrain or adversely affect the functionality or features of the Online Public Access Catalog."
  },
  {
   "ref": "C280",
   "source_doc_id": "D18",
   "name": "Record Data Specifications",
   "description": "The product must provide complete data specifications for authority, bibliographic, order, item, hold/request, and other records maintained or accessed by the management processes, enabling staff to understand the data structures used for queries."
  },
  {
   "ref": "C281",
   "source_doc_id": "D18",
   "name": "Process Overview Documentation",
   "description": "The product must provide thorough high-level documentation of major processes, including bibliographic-record import and export, validation of bibliographic records against internal and external authority sources, and standard reports."
  },
  {
   "ref": "C282",
   "source_doc_id": "D18",
   "name": "Online Cross-Linked Help",
   "description": "The system must provide online HTML help that is hierarchical and cross-linked, describes and illustrates all system functions, and is available without requiring staff to leave the system."
  },
  {
   "ref": "C283",
   "source_doc_id": "D18",
   "name": "Actionable Error Feedback",
   "description": "The system must provide thorough high-level error reporting and feedback and must provide low-level, query-specific feedback through the front-end interface to Local and Global System Administrators when report or query operations fail."
  },
  {
   "ref": "C284",
   "source_doc_id": "D18",
   "name": "Vendor Data Interfaces",
   "description": "The management processes must interface with external vendor websites through published APIs and/or automated transfers of standard-format data files, including formats such as USMARC21 and EDIFACT."
  },
  {
   "ref": "C285",
   "source_doc_id": "D18",
   "name": "Acquisitions Cataloging Integration",
   "description": "The management processes must use the data structures and functionality of the enterprise library automation system's Acquisitions and Cataloging modules when reporting on acquisitions and cataloging data."
  },
  {
   "ref": "C286",
   "source_doc_id": "D18",
   "name": "OPAC Data Querying",
   "description": "The management processes must interact with the Online Public Access Catalog and query patron-related data created there, including holds and circulation data."
  },
  {
   "ref": "C287",
   "source_doc_id": "D19",
   "name": "Relational Database Backend",
   "description": "The Management Processes reporting system must use a fully relational database back end and operate with the relational data structure without requiring denormalized reporting data."
  },
  {
   "ref": "C288",
   "source_doc_id": "D19",
   "name": "Standards-Compliant HTML",
   "description": "The system must produce HTML output that validates against W3C standards for the web-based interface, online help system, and report output, supporting compatibility with different browsers and assistive technologies."
  },
  {
   "ref": "C289",
   "source_doc_id": "D19",
   "name": "Environment Configuration Migration",
   "description": "The system must support migration of configurations between separate development, training, and production environments by exporting and importing templates, permission settings, and saved queries."
  },
  {
   "ref": "C290",
   "source_doc_id": "D19",
   "name": "Safe Training Environment",
   "description": "The training environment must allow staff to experiment without risking production data."
  },
  {
   "ref": "C291",
   "source_doc_id": "D19",
   "name": "Role-Based Access Control",
   "description": "The system must provide security groups and/or roles for individuals, workgroups, and arbitrary staff groups, with permission changes managed through role assignments. It must support Global Admin full system access; Local Admin branch-level reporting and configuration; Library Manager execution of approved reports and limited template modification; Staff execution of reports within assigned permissions; and indirect Patron access through OPAC displays."
  },
  {
   "ref": "C292",
   "source_doc_id": "D19",
