  },
  {
   "index": 67,
   "name": "Consortium Statistical Reports",
   "description": "The Global System Administrator must be able to generate statistical reports for the entire library consortium."
  },
  {
   "index": 68,
   "name": "Data Quality Reports",
   "description": "The system must provide data-quality reports identifying invalid item types, excessively long call numbers, bibliographic records without items, and other data problems."
  },
  {
   "index": 69,
   "name": "Vendor Data Integration",
   "description": "Management processes must exchange standard-format data with vendor websites through published APIs or automated transfers, including USMARC21 and EDIFACT, and must continue to function when vendor data is unavailable at a branch."
  },
  {
   "index": 70,
   "name": "Acquisitions Cataloging Integration",
   "description": "Management processes must read and use the data structures and functionality of the enterprise Library Automation System, including Acquisitions and Cataloging, without managing those functions."
  },
  {
   "index": 71,
   "name": "OPAC Data Querying",
   "description": "Management processes must query patron-interface data created in the OPAC, including holds and circulation, without modifying that data."
  },
  {
   "index": 72,
   "name": "Report Types",
   "description": "The reporting interface must provide canned reports, noncanned on-demand reports, and open-template reports with selectable attributes for circulation, items, patrons, bills, and bibliographic records."
  },
  {
   "index": 73,
   "name": "Scheduled Canned Reports",
   "description": "Users must be able to run product-delivered canned reports using yesterday's, last week's, last month's, or last year's data, select multiple canned reports, and combine their output in one document."
  },
  {
   "index": 74,
   "name": "On Demand Reports",
   "description": "The system must provide on-demand reports based on preselected criteria for maintenance and collection-development activities."
  },
  {
   "index": 75,
   "name": "Report Scheduling",
   "description": "Users must be able to run reports as soon as possible or schedule them hourly, daily, weekly, monthly, or yearly, including recurring reports that can be edited by changing selections or email addresses."
  },
  {
   "index": 76,
   "name": "Report Export Formats",
   "description": "Report output must be available in Excel-compatible, HTML, and CSV formats, with Excel exports avoiding unnecessary duplicate rows."
  },
  {
   "index": 77,
   "name": "Email Report Delivery",
   "description": "The system must deliver reports by email, allow users to enter recipients, and provide an address book for regularly used addresses."
  },
  {
   "index": 78,
   "name": "Comparative Report Output",
   "description": "Reports must support comparative columns such as last month's circulation, the previous month's circulation, percentage differences, and the corresponding month of the previous year."
  },
  {
   "index": 79,
   "name": "Report Queue Prioritization",
   "description": "Authorized users or processes must be able to prioritize selected report types so important reports execute ahead of lower-priority or resource-consuming reports."
  },
  {
   "index": 80,
   "name": "Item Use Metrics",
   "description": "Reports must provide total item-use counts and counts by fiscal-year, month, or other usage date range, including checkout, renewal, and non-cataloged circulation breakdowns."
  },
  {
   "index": 81,
   "name": "File Based Filtering",
   "description": "Users must be able to upload a text file containing values such as barcodes or TCNs and use those values as report filters."
  },
  {
   "index": 82,
   "name": "Notice Reports",
   "description": "The system must report pre-overdue notices, overdue notices, and holds notices sent."
  },
  {
   "index": 83,
   "name": "Pivot Table Output",
   "description": "The reporting system must provide pivot-table output."
  },
  {
   "index": 84,
   "name": "Report Accuracy",
   "description": "Report output must be tested and demonstrated to be accurate and dependable."
  },
  {
   "index": 85,
   "name": "Report Cancellation",
   "description": "Users must be able to cancel scheduled, queued, or currently running reports, including during processing."
  },
  {
   "index": 86,
   "name": "Null Field Inclusion",
   "description": "Report results must include null and blank fields rather than excluding records or values containing them."
  },
  {
   "index": 87,
   "name": "Real Time Reporting",
   "description": "The system must support reports using current data in real time, including activity during busy periods."
  },
  {
   "index": 88,
   "name": "Historical Reporting",
   "description": "The system must provide historical reporting through preserved data or a reporting warehouse, retrieving values as they existed at a specified date or date range, including past bills and shelving locations."
  },
  {
   "index": 89,
   "name": "Survey Name Filtering",
   "description": "Users must be able to select a survey by name for filtering, with the system resolving the name to its survey identifier internally."
  },
  {
   "index": 90,
   "name": "MARC Row Consolidation",
   "description": "Reports must retrieve specified MARC fields and display them on one row even when the fields are stored across multiple rows."
  },
  {
   "index": 91,
   "name": "Workstation Transaction Reports",
   "description": "The system must report transactions for a specified date and time, workstation, or staff member."
  },
  {
   "index": 92,
   "name": "Collection Value Reports",
   "description": "The system must report item values from purchase-price or other item-record data for the entire collection or selected portions, including status- or collection-based selections such as longoverdue items or children's DVDs."
  },
  {
   "index": 93,
   "name": "Financial Compliance",
   "description": "Financial reports and data archiving must comply with standard accounting practices and state, county, and municipal auditing requirements."
  },
  {
   "index": 94,
   "name": "Financial Record Association",
   "description": "The system must associate fines, charges, waivers, payments, and ecommerce transactions with relevant patron and item records and support joins between patron and item financial data."
  },
  {
   "index": 95,
   "name": "High Balance Queries",
   "description": "Staff must be able to query patron accounts with balances above a user-specified dollar amount."
  },
  {
   "index": 96,
   "name": "Financial Data Updates",
   "description": "Authorized staff must be able to update financial information easily, and a payment made at a staff desk must be reflected immediately."
  },
  {
   "index": 97,
   "name": "Financial Reports",
   "description": "The system must report patron balances by patron, home branch, and library system; fines and charges by period and charge type; waived fines by period and branch; and payments by period, collecting branch, payment channel, and payment type."
  },
  {
   "index": 98,
   "name": "Payment Audit Ledger",
   "description": "The system must maintain a payment ledger identifying the charge or charges to which each patron payment was applied so payments can be traced and reconciled."
  },
  {
   "index": 99,
   "name": "Circulation Report Suite",
   "description": "The system must provide circulation reports for check-ins, checkouts, overdue items and patron contact information, circulation modifiers, categories, Dewey classification, shelving location, MARC fields, patron county, home branch, age, renewals, non-cataloged circulation, and total circulation by type."
  },
  {
   "index": 100,
   "name": "Item Report Suite",
   "description": "The system must provide item reports for items added, deleted, edited, counted, created within a date range, missing, overdue, in transit, claimed returned, selected by use count, fines-stopped reason, weeding data, collection age, collection value, last-copy status, and batch status conversion."
  },
  {
   "index": 101,
   "name": "Bibliographic Reports",
   "description": "The system must provide bibliographic reports for record counts, edited records, records added by user and branch, records without attached volumes or items, and records missing specified MARC fields."
  },
  {
   "index": 102,
   "name": "Patron Report Suite",
   "description": "The system must provide patron reports for counts, additions by month, demographic categories, survey answers, expiration date, barred and inactive status, notes, and staff-account password-change and expiration dates, including counts by age, county, city, ZIP code, and home branch."
  },
  {
   "index": 103,
   "name": "Hold Report Suite",
   "description": "The system must provide hold reports for purchase alerts, items sent or received for holds, IntraPINES loans, unfilled holds, annual totals, and stale holds remaining beyond the permitted pickup period."
  },
  {
   "index": 104,
   "name": "In House Use Reports",
   "description": "The system must report non-cataloged in-house use by month and cataloged in-house use."
  },
  {
   "index": 105,
   "name": "Transit Report Suite",
   "description": "The system must report items in transit to a destination branch and items in transit by sending branch."
  },
  {
   "index": 106,
   "name": "Bills Report Suite",
   "description": "The system must provide reports for current patron bills, detailed payments, forgive/work/goods payments, voids, and aged debt with detailed aging periods."
  },
  {
   "index": 107,
   "name": "Activity Cross Tabulation",
   "description": "Activity reports must show checkouts, check-ins, holds placed, and holds filled, cross-tabulated by terminal, branch, library system, hour, patron age range, patron type, and patron location."
  },
  {
   "index": 108,
   "name": "Transaction Grouping",
   "description": "The system must retain detailed transaction history for a configurable number of days, preserve monthly and annual aggregates indefinitely, and group transactions by hour, terminal, branch, system, transaction type, and selected dimensions."
  },
  {
   "index": 109,
   "name": "Checkin Method Counts",
   "description": "The system must count check-ins individually and cumulatively by book drop, terminal, staff or user processing, and self-service."
  },
  {
   "index": 110,
   "name": "Checkout Type Counts",
   "description": "The system must count checkouts individually and cumulatively by staff checkout, self-checkout, staff renewal, self-checkout renewal, online renewal, and OPAC renewal."
  },
  {
   "index": 111,
   "name": "Hold Placement Counts",
   "description": "The system must count hold requests and classify them by placement method, including staff desk, public computer, and remote placement."
  },
  {
   "index": 112,
   "name": "Transaction Summary Reports",
   "description": "The system must report holds placed, holds filled, and checkouts by patron, branch, selected branch groups, library system, and county, including checkout and hold subtotals and hold states such as active, frozen, and frozen-until."
  },
  {
   "index": 113,
   "name": "Accounting Data Retention",
   "description": "The system must archive financial data according to state and local requirements and enforce applicable retention policies, including seven years of audit data where required."
  },
  {
   "index": 114,
   "name": "Snapshot Bills Reports",
   "description": "The system must provide bills reports showing bill information as it existed at a past point in time."
  },
  {
   "index": 115,
   "name": "Separate Item Dates",
   "description": "Item reports must expose last-edit date, last-circulation date, and check-in date and time as separate fields; last-edit date changes only when the item is edited, and renewal timestamps must not be treated as check-ins or edits."
  },
  {
   "index": 116,
   "name": "Report Quick Access",
   "description": "The reporting interface must provide quick access to canned reports and templates, with hover or popup descriptions for report titles and templates."
  },
  {
   "index": 117,
   "name": "Reporting Database Isolation",
   "description": "The system must provide a separate reporting database or replica when needed to isolate reporting workloads from the production database."
  },
  {
   "index": 118,
   "name": "Background Report Processing",
   "description": "Long-running reports must execute in the background or through a queue without occupying the user interface."
  },
  {
   "index": 119,
   "name": "Report Environment Help",
   "description": "The reporting system must provide integrated online help for its reporting interface."
  },
  {
   "index": 120,
   "name": "Vendor And Library Integration",
   "description": "The system must provide a centralized service accepting input from and serving multiple branches as a single reporting source of truth."
  },
  {
   "index": 121,
   "name": "Library Report Templates",
   "description": "The product must provide report templates needed by all consortium member branches for management reporting."
  },
  {
   "index": 122,
   "name": "Director Financial Reports",
   "description": "The system must provide financial reports suitable for library directors and other users requiring director-level financial information."
  },
  {
   "index": 123,
   "name": "Inventory Capacity Reports",
   "description": "The system must provide inventory and capacity reports for staff monitoring collections and operational capacity."
  },
  {
   "index": 124,
   "name": "Management Reporting Scope",
   "description": "The reporting functionality must support management planning, evaluation, and oversight rather than day-to-day patron-facing functions handled by the OPAC and circulation client."
  },
  {
   "index": 125,
   "name": "Report Data Requirements",
   "description": "The system must provide predefined reports and templates covering the management reporting needs of consortium branches."
  },
  {
   "index": 126,
   "name": "Save Reusable Queries",
   "description": "The system must allow staff to save queries and reuse them for repeated reporting activities."
  },
  {
   "index": 127,
   "name": "Select Query Results Manually",
   "description": "The system must allow staff to manually select individual records from query results for subsequent administrative actions."
  }
 ]
