      "type": "too_narrow",
      "requirement_ids": ["R101", "R036"],
      "explanation": "R101 is the detail: CSV export is an output option for the capacity view required by R036."
    },
    {
      "type": "too_narrow",
      "requirement_ids": ["R102", "R037"],
      "explanation": "R102 is the detail: side-by-side branch comparison refines the shelf-space analysis already required by R037."
    },
    {
      "type": "too_narrow",
      "requirement_ids": ["R106", "R038"],
      "explanation": "R106 is the detail: printable pull lists refine the pull-list option already included in R038's transfer capability."
    },
    {
      "type": "too_narrow",
      "requirement_ids": ["R111", "R055"],
