  {
   "index": 7,
   "name": "Collection Analysis Reports",
   "description": "The system must provide reports on weeding data, collection age, collection value, and last-copy status. Collection-value reports must use purchase-price or other item-record data and cover the entire collection or selected portions, including status- or collection-based selections such as longoverdue items or children's DVDs. Last-copy reports must identify items that are the only copy within a selected branch, library system, consortium, bibliographic work, or collection grouping, including deleted last copies where applicable, so catalogers can update WorldCat and avoid inappropriate deletion.",
   "source_doc_ids": [
    "D05",
