{
 "fixed": [
  {
   "name": "Collection And Material Use Reports",
   "description": "The reports interface must enable authorized managers, administrators, and staff to analyze collections and material use for planning, evaluation, and oversight.",
   "priority": "High"
  },
  {
   "name": "Consortium Scale",
   "description": "The system must support a library consortium with 286 branches, 17 million annual circulations, and purchasing and processing exceeding 900,000 items per year.",
   "priority": "High"
  },
  {
   "name": "Cross-Branch Performance Reports",
   "description": "The reports interface must enable analysis of performance across branches.",
   "priority": "High"
  },
  {
   "name": "Role-Based Transfer Access",
   "description": "Administrators must control rights through security groups and roles assigned to individuals, workgroups, and arbitrary staff groups, with changes to role assignments changing permissions. The library automation system must support Global Admin, Local Admin, Library Manager, Staff, and indirect Patron access through the OPAC, with report and transfer permissions appropriate to each role and transfers restricted to authorized roles, including managers, administrators, and transfer coordinators.",
   "priority": "High"
  },
  {
   "name": "Collection Analysis Reports",
   "description": "The system must provide reports on weeding data, collection age, collection value, and last-copy status. Collection-value reports must use purchase-price or other item-record data and cover the entire collection or selected portions, including status- or collection-based selections such as longoverdue items or children's DVDs. Last-copy reports must identify items that are the only copy within a selected branch, library system, consortium, bibliographic work, or collection grouping, including deleted last copies where applicable, so catalogers can update WorldCat and avoid inappropriate deletion.",
   "priority": "High"
  },
  {
   "name": "Item Status and Activity Reports",
   "description": "The system must provide reports on items that are missing, overdue, in transit, claimed returned, selected by use count, or associated with a fines-stopped reason.",
   "priority": "High"
  },
  {
   "name": "Missing Damaged Reports",
   "description": "The system must report missing and damaged items by branch, including condition notes such as water damage or vandalism and selectable periods such as the preceding 30 days or last quarter.",
   "priority": "High"
  },
  {
   "name": "Transit Report Suite",
   "description": "The system must provide reports for items in transit to a destination branch and items in transit by sending branch, including one report combining transit-to and transit-from items that have remained in transit longer than a configurable threshold, defaulting to seven days where specified, using a null arrival date and an overdue departure date; results must be available by branch and library system and sortable by due date.",
   "priority": "High"
  },
  {
   "name": "Checkout and Renewal Reports",
   "description": "The system must provide checkout and renewal reports that count transactions individually and cumulatively by staff checkout, self-checkout, staff renewal, self-checkout renewal, online renewal, and OPAC renewal.",
   "priority": "High"
  },
  {
   "name": "Patron Report Filtering",
   "description": "The system must filter and group patron queries and reports by age range derived from birth date, ZIP code, county, home branch, patron type, and preferred language, and must combine filters with AND and OR logic and applicable circulation conditions.",
   "priority": "High"
  },
  {
   "name": "Background Report Processing",
   "description": "Long-running reports, including inactive patron reports in environments with approximately 3.5 million patrons, must execute as background operations or through a queue without occupying the user interface, and the system must cache slow activity-query results for reuse.",
   "priority": "High"
  },
  {
   "name": "Accounting Data Retention",
   "description": "The system must archive financial data according to state and local requirements and enforce applicable retention policies, including seven years of audit data where required.",
   "priority": "High"
  },
  {
   "name": "Assistive Technology Access",
   "description": "The system must satisfy Section 508 accessibility requirements and support screen readers including JAWS and NVDA, screen magnification including ZoomText, and other assistive technologies; web output must include appropriate alt tags, ARIA labels, semantic structure, and standards-compliant HTML.",
   "priority": "High"
  },
  {
   "name": "Branch Management Reports and Templates",
   "description": "The system must provide predefined reports and report templates needed to cover the management reporting needs of all consortium member branches.",
   "priority": "High"
  },
  {
   "name": "Client And Browser Access",
   "description": "The system must be accessible through a web browser or Windows-compatible client and support Microsoft Internet Explorer 6.0 or later and Mozilla Firefox 2.0 or later.",
   "priority": "High"
  },
  {
   "name": "Cross-Record Query Designer",
   "description": "The system must provide a user-friendly query designer across bibliographic, item, patron, transaction, financial, and other record types, with selectable fields, picklists, regular-expression choices, and Boolean operators.",
   "priority": "High"
  },
  {
   "name": "Indefinite Aggregate Preservation",
   "description": "The system must preserve monthly and annual transaction aggregates indefinitely.",
   "priority": "High"
  },
  {
   "name": "Integrated Accessible System Help",
   "description": "The system must provide hierarchical, cross-linked, searchable HTML help that describes and illustrates system functions, is accessible within the system and to screen readers, and includes integrated online help for the reporting interface.",
   "priority": "High"
  },
  {
   "name": "Management Reporting Scope",
   "description": "The reporting functionality must support management planning, evaluation, and oversight rather than day-to-day patron-facing functions handled by the OPAC and circulation client.",
   "priority": "High"
  },
  {
   "name": "OPAC Preservation",
   "description": "Management and reporting functionality must not constrain, slow, or adversely affect OPAC functionality or patron access.",
   "priority": "High"
  },
  {
   "name": "Open-Hours Performance",
   "description": "Searches and reports must run during open or peak hours without disrupting circulation, other system functions, or the OPAC; background queues, read-only replicas, or equivalent isolation must avoid excessive database contention.",
   "priority": "High"
  },
  {
   "name": "Payment Audit Ledger",
   "description": "The system must maintain a payment ledger identifying the charge or charges to which each patron payment was applied so payments can be traced and reconciled.",
   "priority": "High"
  },
  {
   "name": "Record Data Specifications",
   "description": "The product must provide complete data specifications and dictionaries for authority, bibliographic, order, item, hold/request, and other accessed records, including field names, data types, and relationships.",
   "priority": "High"
  },
  {
   "name": "Relational Database Support",
   "description": "The system must use and operate with a fully relational database, support complex joins, and not require a denormalized reporting schema that can cause synchronization problems.",
   "priority": "High"
  },
  {
   "name": "Report Accuracy",
   "description": "Report output must be tested and demonstrated to be accurate and dependable.",
   "priority": "High"
  },
  {
   "name": "Report Types and Uses",
   "description": "The reporting interface must provide canned reports, noncanned on-demand reports based on preselected criteria for maintenance and collection-development activities, and open-template reports with selectable attributes for circulation, items, patrons, bills, and bibliographic records.",
   "priority": "High"
  },
  {
   "name": "Server Platform Support",
   "description": "The system must operate on Linux and Solaris servers, including Red Hat Enterprise Linux 5 and Solaris 10 on SPARC hardware where specified.",
   "priority": "High"
  },
  {
   "name": "Standards Compliant HTML",
   "description": "Web interfaces, reports, and online help must produce HTML that validates against applicable web standards.",
   "priority": "High"
  },
  {
   "name": "Historical Reporting",
   "description": "The system must provide historical reports through preserved data or a reporting warehouse, retrieving values as they existed at a specified date or date range, including past bills and shelving locations.",
   "priority": "Medium"
  },
  {
   "name": "Material Volume Reporting",
   "description": "The system must report material volume for a specified library system or branch at the current or a historical date, including total items, new acquisitions, material added during selectable periods based on item acquisition dates such as the preceding 30, 60, or 90 days, checked-in items, checked-out items, holds, adult fiction, and board books. Checked-out items must count toward the total, and category groupings must be configurable by library system, such as fiction/non-fiction or format.",
   "priority": "Medium"
  },
  {
   "name": "Branch Capacity And Demographics",
   "description": "The reports interface must enable analysis of branch capacity and patron demographics.",
   "priority": "Medium"
  },
  {
   "name": "Inventory Capacity Reporting",
   "description": "The system must provide authorized staff, including branch managers, with inventory and operational capacity reports for monitoring collections and capacity. The capacity report must provide an all-branch view, allow drilldown to an individual branch, show capacity trends such as growth or shrinkage, support comparison for up to 286 branches, allow users to filter and sort branches by region, library type, and current load, and allow users to export capacity-view data in CSV format.",
   "priority": "Medium"
  },
  {
   "name": "Staff Workflow And Financial Reports",
   "description": "The reports interface must enable analysis of staff workflow and financial transactions.",
   "priority": "Medium"
  },
  {
   "name": "Shelf Space Analysis",
   "description": "The system must provide shelf-space analysis that compares, side by side, for each material genre and format, the percentage of total circulations, the percentage of the collection, and the percentage of total shelf space so users can identify differences and outliers, with views by branch and for the library system, selectable date ranges such as Q1 or Q2, collection percentages based on item counts, circulation percentages based on checkouts, and shelf-space estimates based on item dimensions or item count when dimensions are unavailable.",
   "priority": "Medium"
  },
  {
   "name": "Batch Item Transfers",
   "description": "Authorized staff must be able to transfer selected batches of items between branches and other destinations, including mobile libraries, outreach programs, warehouses, book sales, and event locations, by changing item locations or generating printable pull lists identifying items selected for transfer; the operation must process approximately 9.6 million items without excessive database locking.",
   "priority": "Medium"
  },
  {
   "name": "Transfer Candidate Queries",
   "description": "Staff must be able to query for candidate items for transfer using criteria such as genre, collection area, and circulation inactivity, including items that have not circulated for six months.",
   "priority": "Medium"
  },
  {
   "name": "Transfer Confirmation Preview",
   "description": "Before execution, the system must show a transfer preview containing the item count and source and destination locations and require staff confirmation.",
   "priority": "Medium"
  },
  {
   "name": "Transfer Location Updates",
   "description": "The system must update the location field and associated item records for selected items moved to a new location.",
   "priority": "Medium"
  },
  {
   "name": "Transfer Reversion",
   "description": "The system must return transferred items to their original locations after a configured period or configured event, including a status change to sold or returned or checkout at the destination.",
   "priority": "Medium"
  },
  {
   "name": "Hold and Transit Reports",
   "description": "The system must provide periodic reports for records with holds, item-level holds, in-transit items with holds, and overdue transit.",
   "priority": "Medium"
  },
  {
   "name": "Item Change and Inventory Reports",
   "description": "The system must provide reports on items that were added, deleted, edited, counted, or created within a specified date range.",
   "priority": "Medium"
  },
  {
   "name": "Item Circulation and Status Reports",
   "description": "The system must provide periodic reports for items not checked out for a configurable period, last copies, and missing items.",
   "priority": "Medium"
  },
  {
   "name": "Confirmed Purge Deletion",
   "description": "The system must require a separate confirmation before executing purge deletions.",
   "priority": "Medium"
  },
  {
   "name": "Deletion Audit Recording",
   "description": "The system must record completed and denied deletion attempts, including who performed or attempted each deletion, the record type, record ID, timestamp, user branch, library system, and, where required, the deletion reason.",
   "priority": "Medium"
  },
  {
   "name": "Protected Purge Reports",
   "description": "Reports identifying purge candidates must be read-only and must not delete or modify candidate records.",
   "priority": "Medium"
  },
  {
   "name": "Purge Candidate Identification",
   "description": "The system must identify item records eligible for purging using customizable status, duration, and circulation criteria, including missing, discard/weed, or damaged status, time in status, and no circulation for a specified period; criteria must support Boolean combinations such as missing for six months and no circulation for two years.",
   "priority": "Medium"
  },
  {
   "name": "Activity Cross-Tabulation",
   "description": "Activity reports must show counts of checkouts, check-ins, holds placed, and holds filled, cross-tabulated by terminal, branch, library system, hour, patron age range, patron type, and patron location, and must classify hold-request counts by placement method, including staff desk, public computer, and remote placement.",
   "priority": "Medium"
  },
  {
   "name": "Check-In Method Reports",
   "description": "The system must provide check-in reports that count check-ins individually and cumulatively by book drop, terminal, staff or user processing, and self-service.",
   "priority": "Medium"
  },
  {
   "name": "Circulation Attribute Reports",
   "description": "The system must provide circulation reports using patron contact information, circulation modifiers, categories, patron county, home branch, and age, as well as item Dewey classification, shelving location, and MARC fields.",
   "priority": "Medium"
  },
  {
   "name": "Inactive Patron Reporting",
   "description": "The system must provide an inactive patron report for patrons with no circulation and no electronic activity during a configurable preceding period, where the threshold supports any number of days including 30, 90, 180, and 365 and electronic activity includes OPAC or patron-account logins, online holds, online renewals, and integrated digital-resource access. The report must separate patrons with outstanding fines, allow exclusion of patrons marked do-not-disturb, VIP patrons, staff members, and patrons who opted out of communications, include each patron's current mailing address, support CSV export for upload to an outreach system, and list or group results by configurable organizational scopes including the library system, home branch, and county so users can see system totals and assign work to branches.",
   "priority": "Medium"
  },
  {
   "name": "Null and Blank Field Inclusion",
   "description": "Patron queries and reports must include records and values with null or blank fields, including patrons whose optional demographic fields are null or blank, rather than silently excluding them.",
   "priority": "Medium"
  },
  {
   "name": "Overdue and Volume Reports",
   "description": "The system must provide reports for overdue items, non-cataloged circulation, and total circulation by type.",
   "priority": "Medium"
  },
  {
   "name": "Patron Additions and Status",
   "description": "The system must provide patron reports showing additions by month, expiration date, and barred or inactive status.",
   "priority": "Medium"
  },
  {
   "name": "Patron Counts and Demographics",
   "description": "The system must provide a patron report with total counts and counts by age, county, city, ZIP code, and home branch.",
   "priority": "Medium"
  },
  {
   "name": "Report Export Formats",
   "description": "Report output must be available in Excel-compatible, HTML, and CSV formats, with Excel exports avoiding unnecessary duplicate rows.",
   "priority": "Medium"
  },
  {
   "name": "Acquisitions Cataloging Integration",
   "description": "Management processes must read and use the data structures and functionality of the enterprise Library Automation System, including Acquisitions and Cataloging, without managing those functions.",
   "priority": "Medium"
  },
  {
   "name": "Anonymized Demographic Statistics",
   "description": "The system must provide anonymized transaction and patron statistics by geographic region, ZIP code, age range, and other useful demographic attributes without disclosing personally identifiable information.",
   "priority": "Medium"
  },
  {
   "name": "Bibliographic Reports",
   "description": "The system must provide bibliographic reports for record counts, edited records, records added by user and branch, records without attached volumes or items, and records missing specified MARC fields.",
   "priority": "Medium"
  },
  {
   "name": "Bills Report Suite",
   "description": "The system must provide reports for current patron bills, detailed payments, forgive/work/goods payments, voids, and aged debt with detailed aging periods.",
   "priority": "Medium"
  },
  {
   "name": "Board and Executive Reports",
   "description": "The system must provide predefined reports for library boards and executive users.",
   "priority": "Medium"
  },
  {
   "name": "Centralized Branch Reporting Service",
   "description": "The system must provide a centralized service that accepts input from and serves multiple branches as a single reporting source of truth.",
   "priority": "Medium"
  },
  {
   "name": "Configuration Migration",
   "description": "The system must export and import report templates, permission settings, saved queries, and other configuration between development, training, and production environments.",
   "priority": "Medium"
  },
  {
   "name": "Consortium Statistical Reports",
   "description": "The Global System Administrator must be able to generate statistical reports for the entire library consortium.",
   "priority": "Medium"
  },
  {
   "name": "Detailed Transaction Retention",
   "description": "The system must retain detailed transaction history for a configurable number of days.",
   "priority": "Medium"
  },
  {
   "name": "Director-Level Financial Reports",
   "description": "The system must provide financial reports suitable for library directors and other users requiring director-level financial information, including patron balances by patron, home branch, and library system, fines and charges by period and charge type, waived fines by period and branch, and payments by period, collecting branch, payment channel, and payment type.",
   "priority": "Medium"
  },
  {
   "name": "Environment Separation",
   "description": "The product must provide separate development and training environments, including a training environment safe for experimentation without affecting production.",
   "priority": "Medium"
  },
  {
   "name": "Error Feedback",
   "description": "The system must provide high-level error reporting and low-level query-specific feedback to administrators, including relevant table, field, and error type when available.",
   "priority": "Medium"
  },
  {
   "name": "Financial Data Updates",
   "description": "Authorized staff must be able to update financial information easily, and a payment made at a staff desk must be reflected immediately.",
   "priority": "Medium"
  },
  {
   "name": "Financial Record Association",
   "description": "The system must associate fines, charges, waivers, payments, and ecommerce transactions with relevant patron and item records and support joins between patron and item financial data.",
   "priority": "Medium"
  },
  {
   "name": "Georgia Annual Report",
   "description": "The system must provide the Georgia Annual Report as a report for state reporting.",
   "priority": "Medium"
  },
  {
   "name": "Hold Report Suite",
   "description": "The system must provide hold reports for purchase alerts, items sent or received for holds, IntraPINES loans, unfilled holds, annual totals, and stale holds remaining beyond the permitted pickup period.",
   "priority": "Medium"
  },
  {
   "name": "OPAC Data Querying",
   "description": "Management processes must query patron-interface data created in the OPAC, including holds and circulation, without modifying that data.",
   "priority": "Medium"
  },
  {
   "name": "Patron Behavior Statistics",
   "description": "The system must produce statistics about patron behavior and material use, including return speed, renewal likelihood, renewal rates, and the percentage of branch checkouts that are renewals.",
   "priority": "Medium"
  },
  {
   "name": "Pivot Table Output",
   "description": "The reporting system must provide pivot-table output.",
   "priority": "Medium"
  },
  {
   "name": "Process Documentation",
   "description": "The product must document major processes, including bibliographic import and export, validation against internal and external authority sources, and standard reports.",
   "priority": "Medium"
  },
  {
   "name": "Query Criteria Display",
   "description": "Report results must display the query selections, report name, and selected date criteria used to produce them.",
   "priority": "Medium"
  },
  {
   "name": "Query Designer Administration",
   "description": "The system must allow administrators to control the tables, fields, and tool access available in the query designer.",
   "priority": "Medium"
  },
  {
   "name": "Real Time Reporting",
   "description": "The system must support reports using current data in real time, including activity during busy periods.",
   "priority": "Medium"
  },
  {
   "name": "Report Cancellation",
   "description": "Users must be able to cancel scheduled, queued, or currently running reports, including during processing.",
   "priority": "Medium"
  },
  {
   "name": "Report Permission Administration",
   "description": "The system must provide fine-grained permissions for creating, cloning, running, and accessing reports, filters, data sets, and shared folders, including administrator-controlled shared folders that allow or prohibit specific report access.",
   "priority": "Medium"
  },
  {
   "name": "Report Queue Monitoring",
   "description": "Users must be able to see report queue contents, position, number of reports ahead, submission time, and status such as waiting, running, completed, or failed.",
   "priority": "Medium"
  },
  {
   "name": "Report Queue Prioritization",
   "description": "Authorized users or processes must be able to prioritize selected report types so important reports execute ahead of lower-priority or resource-consuming reports.",
   "priority": "Medium"
  },
  {
   "name": "Report Scheduling",
   "description": "Users must be able to run reports as soon as possible or schedule them hourly, daily, weekly, monthly, or yearly, including recurring reports that can be edited by changing selections or email addresses.",
   "priority": "Medium"
  },
  {
   "name": "Report Template Controls",
   "description": "Authorized administrators must create shared report templates that staff can run as-is or modify within controlled limits on filters and display fields, without compromising intended results or exposing deleted items; authorized users must be able to clone templates and edit permitted display options.",
   "priority": "Medium"
  },
  {
   "name": "Save Reusable Queries",
   "description": "The system must allow staff to save queries and reuse them for repeated reporting activities.",
   "priority": "Medium"
  },
  {
   "name": "Staff Authentication",
   "description": "The system must support optional employee-card or badge login and individual username-and-password login as a fallback; every login must identify the individual staff member and card login must not bypass individual authentication.",
   "priority": "Medium"
  },
  {
   "name": "State Aid Statistics",
   "description": "The system must provide Application for State Aid statistics as a report for state reporting.",
   "priority": "Medium"
  },
  {
   "name": "Track Uncataloged Materials",
   "description": "The system must track uncataloged items, including paperback books and children's board books, before catalog records exist.",
   "priority": "Medium"
  },
  {
   "name": "Traffic Usage Cross-Tabulations",
   "description": "The system must provide traffic and usage report cross-tabulations by terminal, branch, library system, hour, age range, patron type, and patron location.",
   "priority": "Medium"
  },
  {
   "name": "Transaction Analysis Grouping",
   "description": "The system must group transactions for analysis by hour, terminal, branch, library system, transaction type, and selected dimensions.",
   "priority": "Medium"
  },
  {
   "name": "Transaction Summary Reports",
   "description": "The system must report holds placed, holds filled, and checkouts by patron, branch, selected branch groups, library system, and county, including checkout and hold subtotals and hold states such as active, frozen, and frozen-until.",
   "priority": "Medium"
  },
  {
   "name": "Workstation Transaction Reports",
   "description": "The system must report transactions for a specified date and time, workstation, or staff member.",
   "priority": "Medium"
  },
  {
   "name": "Reporting Database Isolation",
   "description": "The system must provide a separate reporting database or replica when needed to isolate reporting workloads from the production database.",
   "priority": "Medium"
  },
  {
   "name": "Separate Item Dates",
   "description": "Item reports must expose last-edit date, last-circulation date, and check-in date and time as separate fields; last-edit date changes only when the item is edited, and renewal timestamps must not be treated as check-ins or edits.",
   "priority": "Medium"
  },
  {
   "name": "Saved Transfer Queries",
   "description": "Staff must be able to save transfer-candidate queries for repeated use, including monthly reuse, and make saved queries available for reuse or sharing.",
   "priority": "Low"
  },
  {
   "name": "Transfer Audit History",
   "description": "The system must record transfer history for each item, including enough history to determine patterns such as five transfers within one year.",
   "priority": "Low"
  },
  {
   "name": "Transfer Delay Alerts",
   "description": "The system must notify designated staff when a transfer is delayed or encounters an issue.",
   "priority": "Low"
  },
  {
   "name": "Transfer Undo",
   "description": "Staff must be able to undo an erroneous transfer after it has been initiated or completed.",
   "priority": "Low"
  },
  {
   "name": "Transit Label Generation",
   "description": "The system must generate printable barcode transit labels for transferred items.",
   "priority": "Low"
  },
  {
   "name": "Invalid Patron Branch Report",
   "description": "The system must provide a periodic report for patrons with invalid home branches.",
   "priority": "Low"
  },
  {
   "name": "Deletion Data Analysis",
   "description": "The system must support counts and queries of deletion data by branch, library system, date range, user, record type, and highest-volume users.",
   "priority": "Low"
  },
  {
   "name": "Orphan Record Deletion",
   "description": "The system must provide a quick method to delete volume entries with their associated copy entries and records with no attached items.",
   "priority": "Low"
  },
  {
   "name": "Configurable Age Ranges",
   "description": "Users must be able to configure age ranges separately for each patron report, including ranges such as 0–5, 6–10, 11–15 or 0–6, 7–12, 13–17, 18–24, and 25–34.",
   "priority": "Low"
  },
  {
   "name": "Patron Surveys and Notes",
   "description": "The system must provide patron reports showing survey answers and notes.",
   "priority": "Low"
  },
  {
   "name": "Staff Account Date Reports",
   "description": "The system must provide reports showing staff-account password-change dates and password-expiration dates.",
   "priority": "Low"
  },
  {
   "name": "Comparative Report Output",
   "description": "Reports must support comparative columns such as last month's circulation, the previous month's circulation, percentage differences, and the corresponding month of the previous year.",
   "priority": "Low"
  },
  {
   "name": "Distribute Materials Rapidly",
   "description": "The system must support rapid distribution of uncataloged materials with minimal branch labor.",
   "priority": "Low"
  },
  {
   "name": "Email Report Delivery",
   "description": "The system must deliver reports by email, allow users to enter recipients, and provide an address book for regularly used addresses.",
   "priority": "Low"
  },
  {
   "name": "File Based Filtering",
   "description": "Users must be able to upload a text file containing values such as barcodes or TCNs and use those values as report filters.",
   "priority": "Low"
  },
  {
   "name": "High Balance Queries",
   "description": "Staff must be able to query patron accounts with balances above a user-specified dollar amount.",
   "priority": "Low"
  },
  {
   "name": "In House Use Reports",
   "description": "The system must report non-cataloged in-house use by month and cataloged in-house use.",
   "priority": "Low"
  },
  {
   "name": "MARC Row Consolidation",
   "description": "Reports must retrieve specified MARC fields and display them on one row even when the fields are stored across multiple rows.",
   "priority": "Low"
  },
  {
   "name": "Notice Reports",
   "description": "The system must report pre-overdue notices, overdue notices, and holds notices sent.",
   "priority": "Low"
  },
  {
   "name": "Report Quick Access",
   "description": "The reporting interface must provide quick access to canned reports and templates, with hover or popup descriptions for report titles and templates.",
   "priority": "Low"
  },
  {
   "name": "Survey Name Filtering",
   "description": "Users must be able to select a survey by name for filtering, with the system resolving the name to its survey identifier internally.",
   "priority": "Low"
  }
 ],
