 "glossary": [
  {
   "term": "branch",
   "definition": "A physical library service point or other managed library location."
  },
  {
   "term": "library system",
   "definition": "The organization or consortium that contains and manages multiple branches."
  },
  {
   "term": "item",
   "definition": "A physical or uncataloged material record managed by the system."
  },
  {
   "term": "patron",
   "definition": "A person with a library account."
  },
  {
   "term": "report",
   "definition": "A generated presentation or export of queried system data."
  },
  {
   "term": "circulation",
   "definition": "A transaction involving checkout, check-in, renewal, hold activity, or related material use."
  },
  {
   "term": "hold",
   "definition": "A patron request to reserve or obtain an item."
  },
  {
   "term": "status",
   "definition": "The operational condition assigned to an item or record, such as missing, damaged, or discard/weed."
  },
  {
   "term": "OPAC",
   "definition": "The Online Public Access Catalog through which patrons access catalog, hold, and circulation functions."
  },
  {
   "term": "MARC",
   "definition": "The machine-readable cataloging data format used for bibliographic fields."
  },
  {
   "term": "TCN",
   "definition": "A title control number used to identify a bibliographic record."
  },
  {
   "term": "WorldCat",
   "definition": "An external union catalog used for bibliographic and holdings updates."
  },
  {
   "term": "CSV",
   "definition": "A comma-separated values file format used for data export."
  },
  {
   "term": "role",
   "definition": "A named security assignment that determines a user's permissions."
  },
  {
   "term": "library automation system",
   "definition": "The enterprise system providing acquisitions, cataloging, circulation, and related library records."
  }
 ]
