   "index": 33,
   "name": "Material Volume Reporting",
   "description": "The system must report material volume for a specified library system or branch at the current or a historical date, including total items, new acquisitions, material added during selectable periods based on item acquisition dates such as the preceding 30, 60, or 90 days, checked-in items, checked-out items, holds, adult fiction, and board books. Checked-out items must count toward the total, and category groupings must be configurable by library system, such as fiction/non-fiction or format."
  },
  {
   "index": 34,
   "name": "Branch Capacity And Demographics",
   "description": "The reports interface must enable analysis of branch capacity and patron demographics."
  },
  {
   "index": 35,
   "name": "Inventory Capacity Reporting",
   "description": "The system must provide authorized staff, including branch managers, with inventory and operational capacity reports for monitoring collections and capacity. The capacity report must provide an all-branch view, allow drilldown to an individual branch, show capacity trends such as growth or shrinkage, support comparison for up to 286 branches, allow users to filter and sort branches by region, library type, and current load, and allow users to export capacity-view data in CSV format."
  },
  {
   "index": 36,
   "name": "Staff Workflow And Financial Reports",
   "description": "The reports interface must enable analysis of staff workflow and financial transactions."
  },
  {
   "index": 37,
   "name": "Item Use and Circulation Metrics",
   "description": "Reports must identify usage of uncataloged materials and provide total item-use counts, counts by fiscal year, month, or other usage date range, and circulation statistics including checkout, renewal, and other transactions involving uncataloged materials."
  },
  {
   "index": 38,
   "name": "Shelf Space Analysis",
   "description": "The system must provide shelf-space analysis that compares, side by side, for each material genre and format, the percentage of total circulations, the percentage of the collection, and the percentage of total shelf space so users can identify differences and outliers, with views by branch and for the library system, selectable date ranges such as Q1 or Q2, collection percentages based on item counts, circulation percentages based on checkouts, and shelf-space estimates based on item dimensions or item count when dimensions are unavailable."
  },
  {
   "index": 39,
   "name": "Batch Item Transfers",
   "description": "Authorized staff must be able to transfer selected batches of items between branches and other destinations, including mobile libraries, outreach programs, warehouses, book sales, and event locations, by changing item locations or generating printable pull lists identifying items selected for transfer; the operation must process approximately 9.6 million items without excessive database locking."
  },
  {
   "index": 40,
   "name": "Save and Share Queries",
   "description": "The system must allow staff to save queries, including transfer-candidate queries, reuse them for repeated reporting activities including monthly reuse, and make saved queries available for reuse or sharing."
  },
  {
   "index": 41,
   "name": "Select Records for Actions",
   "description": "The system must allow staff to manually select individual records from query results for subsequent administrative actions, including selecting individual titles or items from transfer-query results before executing a transfer, such as selecting 25 items from 100 candidates."
  },
  {
   "index": 42,
   "name": "Transfer Candidate Queries",
   "description": "Staff must be able to query for candidate items for transfer using criteria such as genre, collection area, and circulation inactivity, including items that have not circulated for six months."
  },
  {
   "index": 43,
   "name": "Transfer Confirmation Preview",
   "description": "Before execution, the system must show a transfer preview containing the item count and source and destination locations and require staff confirmation."
  },
  {
   "index": 44,
   "name": "Transfer Location Updates",
   "description": "The system must update the location field and associated item records for selected items moved to a new location."
  },
  {
   "index": 45,
   "name": "Transfer Reversion",
   "description": "The system must return transferred items to their original locations after a configured period or configured event, including a status change to sold or returned or checkout at the destination."
  },
  {
   "index": 46,
   "name": "Batch Item Status Conversion",
   "description": "The system must provide a workflow that converts many selected items from one status to another in a single batch, such as changing 100 missing items to discard/weed."
  },
  {
   "index": 47,
   "name": "Data Quality and Integrity Reports",
   "description": "The system must provide periodic data-quality reports identifying invalid item types, excessively long call numbers, bibliographic records without items, and other data problems."
  },
  {
   "index": 48,
   "name": "Hold and Transit Reports",
   "description": "The system must provide periodic reports for records with holds, item-level holds, in-transit items with holds, and overdue transit."
  },
  {
   "index": 49,
   "name": "Item Change and Inventory Reports",
   "description": "The system must provide reports on items that were added, deleted, edited, counted, or created within a specified date range."
  },
  {
   "index": 50,
   "name": "Item Circulation and Status Reports",
   "description": "The system must provide periodic reports for items not checked out for a configurable period, last copies, and missing items."
  },
  {
   "index": 51,
   "name": "Confirmed Purge Deletion",
   "description": "The system must require a separate confirmation before executing purge deletions."
  },
  {
   "index": 52,
   "name": "Deletion Audit Recording",
   "description": "The system must record completed and denied deletion attempts, including who performed or attempted each deletion, the record type, record ID, timestamp, user branch, library system, and, where required, the deletion reason."
  },
  {
   "index": 53,
   "name": "Protected Purge Reports",
   "description": "Reports identifying purge candidates must be read-only and must not delete or modify candidate records."
  },
  {
   "index": 54,
   "name": "Purge Candidate Identification",
   "description": "The system must identify item records eligible for purging using customizable status, duration, and circulation criteria, including missing, discard/weed, or damaged status, time in status, and no circulation for a specified period; criteria must support Boolean combinations such as missing for six months and no circulation for two years."
  },
  {
   "index": 55,
   "name": "Check-In Method Reports",
   "description": "The system must provide check-in reports that count check-ins individually and cumulatively by book drop, terminal, staff or user processing, and self-service."
  },
  {
   "index": 56,
   "name": "Circulation Attribute Reports",
   "description": "The system must provide circulation reports using patron contact information, circulation modifiers, categories, patron county, home branch, and age, as well as item Dewey classification, shelving location, and MARC fields."
  },
  {
   "index": 57,
   "name": "Inactive Patron Reporting",
   "description": "The system must provide an inactive patron report for patrons with no circulation and no electronic activity during a configurable preceding period, where the threshold supports any number of days including 30, 90, 180, and 365 and electronic activity includes OPAC or patron-account logins, online holds, online renewals, and integrated digital-resource access. The report must separate patrons with outstanding fines, allow exclusion of patrons marked do-not-disturb, VIP patrons, staff members, and patrons who opted out of communications, include each patron's current mailing address, support CSV export for upload to an outreach system, and list or group results by configurable organizational scopes including the library system, home branch, and county so users can see system totals and assign work to branches."
  },
  {
   "index": 58,
   "name": "Null and Blank Field Inclusion",
   "description": "Patron queries and reports must include records and values with null or blank fields, including patrons whose optional demographic fields are null or blank, rather than silently excluding them."
  },
  {
   "index": 59,
   "name": "Overdue and Volume Reports",
   "description": "The system must provide reports for overdue items, non-cataloged circulation, and total circulation by type."
  },
  {
   "index": 60,
   "name": "Patron Additions and Status",
   "description": "The system must provide patron reports showing additions by month, expiration date, and barred or inactive status."
  },
  {
   "index": 61,
   "name": "Patron Counts and Demographics",
   "description": "The system must provide a patron report with total counts and counts by age, county, city, ZIP code, and home branch."
  },
  {
   "index": 62,
   "name": "Patron Report Filtering",
   "description": "The system must let users filter and group patron queries and reports by age range derived from birth date, ZIP code, county, home branch, patron type, and preferred language, combine filters with AND and OR logic and applicable circulation conditions, and configure age ranges separately for each patron report, including ranges such as 0–5, 6–10, 11–15 or 0–6, 7–12, 13–17, 18–24, and 25–34."
  },
  {
   "index": 63,
   "name": "Report Export Formats",
   "description": "Report output must be available in Excel-compatible, HTML, and CSV formats, with Excel exports avoiding unnecessary duplicate rows."
  },
  {
   "index": 64,
   "name": "Acquisitions Cataloging Integration",
   "description": "Management processes must read and use the data structures and functionality of the enterprise Library Automation System, including Acquisitions and Cataloging, without managing those functions."
  },
  {
   "index": 65,
   "name": "Anonymized Demographic Statistics",
   "description": "The system must provide anonymized transaction and patron statistics by geographic region, ZIP code, age range, and other useful demographic attributes without disclosing personally identifiable information."
  },
  {
