   "name": "Bills Report Suite",
   "description": "The system must provide reports for current patron bills, detailed payments, forgive/work/goods payments, voids, and aged debt with detailed aging periods."
  },
  {
   "index": 68,
   "name": "Board and Executive Reports",
   "description": "The system must provide predefined reports for library boards and executive users."
  },
  {
   "index": 69,
   "name": "Branch Operation Without Vendor Data",
   "description": "Management processes must continue to function at a branch when vendor data is unavailable."
  },
  {
   "index": 70,
   "name": "Centralized Branch Reporting Service",
   "description": "The system must provide a centralized service that accepts input from and serves multiple branches as a single reporting source of truth."
