   "description": "Authorized administrators must create shared report templates that staff can run as-is or modify within controlled limits on filters and display fields, without compromising intended results or exposing deleted items; authorized users must be able to clone templates and edit permitted display options."
  },
  {
   "index": 97,
   "name": "Run Canned Reports by Period",
   "description": "Users must be able to run product-delivered canned reports using yesterday's, last week's, last month's, or last year's data."
  },
  {
   "index": 98,
   "name": "Staff Authentication",
   "description": "The system must support optional employee-card or badge login and individual username-and-password login as a fallback; every login must identify the individual staff member and card login must not bypass individual authentication."
  },
  {
   "index": 99,
   "name": "State Aid Statistics",
   "description": "The system must provide Application for State Aid statistics as a report for state reporting."
  },
  {
   "index": 100,
   "name": "Track Uncataloged Materials",
   "description": "The system must track uncataloged items, including paperback books and children's board books, before catalog records exist."
  },
  {
   "index": 101,
   "name": "Transaction Analysis Grouping",
   "description": "The system must group transactions for analysis by hour, terminal, branch, library system, transaction type, and selected dimensions."
  },
  {
   "index": 102,
   "name": "Transaction Summary Reports",
   "description": "The system must report holds placed, holds filled, and checkouts by patron, branch, selected branch groups, library system, and county, including checkout and hold subtotals and hold states such as active, frozen, and frozen-until."
  },
  {
   "index": 103,
   "name": "Vendor Data Exchange",
   "description": "Management processes must exchange standard-format data with vendor websites through published APIs or automated transfers, including USMARC21 and EDIFACT."
  },
  {
   "index": 104,
   "name": "Workstation Transaction Reports",
   "description": "The system must report transactions for a specified date and time, workstation, or staff member."
  },
  {
   "index": 105,
   "name": "Separate Item Dates",
   "description": "Item reports must expose last-edit date, last-circulation date, and check-in date and time as separate fields; last-edit date changes only when the item is edited, and renewal timestamps must not be treated as check-ins or edits."
  },
  {
   "index": 106,
   "name": "Transfer Audit History",
   "description": "The system must record transfer history for each item, including enough history to determine patterns such as five transfers within one year."
  },
  {
   "index": 107,
   "name": "Transfer Delay Alerts",
   "description": "The system must notify designated staff when a transfer is delayed or encounters an issue."
  },
  {
   "index": 108,
   "name": "Transfer Undo",
   "description": "Staff must be able to undo an erroneous transfer after it has been initiated or completed."
  },
  {
   "index": 109,
   "name": "Transit Label Generation",
   "description": "The system must generate printable barcode transit labels for transferred items."
  },
  {
   "index": 110,
   "name": "Invalid Patron Branch Report",
   "description": "The system must provide a periodic report for patrons with invalid home branches."
  },
  {
   "index": 111,
   "name": "Deletion Data Analysis",
   "description": "The system must support counts and queries of deletion data by branch, library system, date range, user, record type, and highest-volume users."
  },
  {
   "index": 112,
   "name": "Orphan Record Deletion",
   "description": "The system must provide a quick method to delete volume entries with their associated copy entries and records with no attached items."
  },
  {
   "index": 113,
   "name": "Patron Surveys and Notes",
   "description": "The system must provide patron reports showing survey answers and notes."
  },
  {
   "index": 114,
   "name": "Staff Account Date Reports",
   "description": "The system must provide reports showing staff-account password-change dates and password-expiration dates."
  },
  {
   "index": 115,
   "name": "Combine Multiple Report Outputs",
   "description": "Users must be able to select multiple product-delivered canned reports and combine their output in one document."
  },
  {
   "index": 116,
   "name": "Comparative Report Output",
   "description": "Reports must support comparative columns such as last month's circulation, the previous month's circulation, percentage differences, and the corresponding month of the previous year."
  },
  {
   "index": 117,
   "name": "Distribute Materials Rapidly",
   "description": "The system must support rapid distribution of uncataloged materials with minimal branch labor."
  },
  {
   "index": 118,
   "name": "File Based Filtering",
   "description": "Users must be able to upload a text file containing values such as barcodes or TCNs and use those values as report filters."
  },
  {
   "index": 119,
   "name": "Financial Information Updates",
   "description": "Authorized staff must be able to update financial information easily."
  },
  {
   "index": 120,
   "name": "High Balance Queries",
   "description": "Staff must be able to query patron accounts with balances above a user-specified dollar amount."
  },
  {
   "index": 121,
   "name": "In House Use Reports",
   "description": "The system must report non-cataloged in-house use by month and cataloged in-house use."
  },
  {
   "index": 122,
   "name": "MARC Row Consolidation",
   "description": "Reports must retrieve specified MARC fields and display them on one row even when the fields are stored across multiple rows."
  },
  {
   "index": 123,
   "name": "Notice Reports",
   "description": "The system must report pre-overdue notices, overdue notices, and holds notices sent."
  },
  {
   "index": 124,
   "name": "Report Quick Access",
   "description": "The reporting interface must provide quick access to canned reports and templates, with hover or popup descriptions for report titles and templates."
  },
  {
   "index": 125,
   "name": "Report Recipient Address Book",
   "description": "The system must provide an address book for users to store regularly used email addresses."
  },
  {
   "index": 126,
   "name": "Survey Name Filtering",
   "description": "Users must be able to select a survey by name for filtering, with the system resolving the name to its survey identifier internally."
  }
 ]
}

